var e=[{id:`od-01`,movement:`opening_doxology`,speaker:`deacon`,mode:`aloud`,cue:`(aloud)`,text:`Bless, Master.`,pointing:null,source_page:31,note:`Printed inline annotation '(aloud)' — the source's own wording, rendered as the cue.`},{id:`od-02`,movement:`opening_doxology`,speaker:`rubric`,text:`The priest kisses the Holy Gospel, lifts it up with both hands, and lowering it, blesses the Holy Table cross-wise, saying:`,pointing:null,source_page:31,note:`ABSENT`},{id:`od-03`,movement:`opening_doxology`,speaker:`priest`,mode:null,text:`Blessèd is the Kingdom of the Father, and of the Son, and of the Holy Spirit, now and ever, and unto ages of ages.`,pointing:null,source_page:31,note:`Diacritic in 'Blessèd' retained verbatim. Not marked '(aloud)' in source despite being audible.`},{id:`od-04`,movement:`opening_doxology`,speaker:`choir`,text:`Amen.`,pointing:null,source_page:31,note:`ABSENT`},{id:`gl-heading`,movement:`great_litany`,speaker:`heading`,text:`GREAT LITANY`,pointing:null,source_page:31,note:`ABSENT`},{id:`gl-01`,movement:`great_litany`,speaker:`deacon`,mode:null,text:`In peace let us pray to the Lord.`,pointing:null,source_page:31,note:`ABSENT`},{id:`gl-02`,movement:`great_litany`,speaker:`choir`,text:`Lord, have mercy.`,pointing:null,source_page:31,note:`ABSENT`},{id:`gl-03`,movement:`great_litany`,speaker:`deacon`,mode:null,text:`For the peace from above and for the salvation of our souls, let us pray to the Lord.`,pointing:null,source_page:31,note:`ABSENT`},{id:`gl-04`,movement:`great_litany`,speaker:`choir`,text:`Lord, have mercy.`,pointing:null,source_page:31,note:`ABSENT`},{id:`gl-05`,movement:`great_litany`,speaker:`deacon`,mode:null,text:`For the peace of the whole world, for the welfare of the holy churches of God, and for the union of all, let us pray to the Lord.`,pointing:null,source_page:31,note:`ABSENT`},{id:`gl-06`,movement:`great_litany`,speaker:`choir`,text:`Lord, have mercy.`,pointing:null,source_page:31,note:`ABSENT`},{id:`gl-07`,movement:`great_litany`,speaker:`deacon`,mode:null,text:`For this holy temple and for those who enter with faith, reverence, and the fear of God, let us pray to the Lord.`,pointing:null,source_page:31,note:`ABSENT`},{id:`gl-08`,movement:`great_litany`,speaker:`choir`,text:`Lord, have mercy.`,pointing:null,source_page:31,note:`ABSENT`},{id:`gl-09`,movement:`great_litany`,speaker:`deacon`,mode:null,text:`For our lord His Beatitude, the Most blessèd Metropolitan ___, for our lord His Eminence, the Most reverend Archbishop (His Grace, the Right reverend Bishop) ___, for the honorable priesthood, the diaconate in Christ, for all the clergy and the people, let us pray to the Lord.`,pointing:null,source_page:31,note:`Blanks ('___') are printed placeholders for local hierarchs' names, retained verbatim — parish/diocese-specific, cf. templeDedication pattern (dismissal_assembler_spec.md §7.1).`},{id:`gl-10`,movement:`great_litany`,speaker:`choir`,text:`Lord, have mercy.`,pointing:null,source_page:32,note:`Resolves the page-break gap flagged during the page-31 test encode — confirmed against this scan, not inferred from pattern.`},{id:`gl-11`,movement:`great_litany`,speaker:`deacon`,mode:null,text:`For this country, its President {{(or title of the highest civil authority)}}, for all civil authorities, and for the armed forces everywhere, let us pray to the Lord.`,pointing:null,source_page:32,note:`'{{...}}' marks the red-ink inline editorial alternative per spec v4 — renders in rubric red, braces stripped at render time.`},{id:`gl-12`,movement:`great_litany`,speaker:`choir`,text:`Lord, have mercy.`,pointing:null,source_page:32,note:`ABSENT`},{id:`gl-13`,movement:`great_litany`,speaker:`deacon`,mode:null,text:`For this city {{(or village, or holy habitation)}}, for every city and country, and for the faithful dwelling in them, let us pray to the Lord.`,pointing:null,source_page:32,note:`'{{...}}' marks the red-ink inline editorial alternative per spec v4 — same pattern as gl-11.`},{id:`gl-14`,movement:`great_litany`,speaker:`choir`,text:`Lord, have mercy.`,pointing:null,source_page:32,note:`ABSENT`},{id:`gl-15`,movement:`great_litany`,speaker:`deacon`,mode:null,text:`For seasonable weather, for abundance of the fruits of the earth, and for peaceful times, let us pray to the Lord.`,pointing:null,source_page:32,note:`ABSENT`},{id:`gl-16`,movement:`great_litany`,speaker:`choir`,text:`Lord, have mercy.`,pointing:null,source_page:32,note:`ABSENT`},{id:`gl-17`,movement:`great_litany`,speaker:`deacon`,mode:null,text:`For travelers by land, by sea, and by air; for the sick and the suffering; for captives and their salvation, let us pray to the Lord.`,pointing:null,source_page:32,note:`ABSENT`},{id:`gl-18`,movement:`great_litany`,speaker:`choir`,text:`Lord, have mercy.`,pointing:null,source_page:32,note:`ABSENT`},{id:`gl-19`,movement:`great_litany`,speaker:`deacon`,mode:null,text:`For our deliverance from all affliction, wrath, danger, and necessity, let us pray to the Lord.`,pointing:null,source_page:32,note:`ABSENT`},{id:`gl-20`,movement:`great_litany`,speaker:`choir`,text:`Lord, have mercy.`,pointing:null,source_page:32,note:`ABSENT`},{id:`gl-21`,movement:`great_litany`,speaker:`deacon`,mode:null,text:`Help us, save us, have mercy on us, and keep us O God, by Thy grace.`,pointing:null,source_page:32,note:`ABSENT`},{id:`gl-22`,movement:`great_litany`,speaker:`choir`,text:`Lord, have mercy.`,pointing:null,source_page:32,note:`ABSENT`},{id:`gl-23`,movement:`great_litany`,speaker:`deacon`,mode:null,text:`Commemorating our most holy, most pure, most blessèd and glorious Lady Theotokos and Ever-Virgin Mary with all the saints, let us commend ourselves and each other, and all our life unto Christ our God.`,pointing:null,source_page:32,note:`ABSENT`},{id:`gl-24`,movement:`great_litany`,speaker:`choir`,text:`To Thee, O Lord.`,pointing:null,source_page:33,note:`ABSENT`},{id:`gl-25`,movement:`great_litany`,speaker:`rubric`,text:`During the Litany, the priest quietly recites the prayer of the First Antiphon:`,pointing:null,source_page:33,note:`ABSENT`},{id:`gl-26`,movement:`great_litany`,speaker:`priest`,mode:`quiet`,text:`O Lord our God, Whose power is incomparable, Whose glory is incomprehensible, Whose mercy is immeasurable, and love for man ineffable, do Thou, O Master, according to Thy goodness, look down upon us and upon this holy temple, and show us and those who pray with us the richness of Thy mercy and Thy compassion.`,pointing:null,source_page:33,note:`mode:quiet confirmed by both the rubric wording and italic typesetting in source.`},{id:`gl-27`,movement:`great_litany`,speaker:`heading`,text:`Exclamation:`,pointing:null,source_page:33,note:`ABSENT`},{id:`gl-28`,movement:`great_litany`,speaker:`priest`,mode:`aloud`,text:`For unto Thee are due all glory, honor, and worship: to the Father, and to the Son, and to the Holy Spirit, now and ever, and unto ages of ages.`,pointing:null,source_page:33,note:`mode:aloud confirmed by both the 'Exclamation:' cue heading and upright typesetting in source.`},{id:`gl-29`,movement:`great_litany`,speaker:`choir`,text:`Amen.`,pointing:null,source_page:33,note:`ABSENT`},{id:`a1-heading`,movement:`antiphon_1`,speaker:`heading`,text:`FIRST ANTIPHON *`,pointing:null,source_page:33,note:`Asterisk ties to footnote a1-footnote.`},{id:`a1-01`,movement:`antiphon_1`,speaker:`rubric`,text:`During the singing of the First Antiphon, the deacon, having bowed to the Holy Table, steps aside and stands before the icon of Christ.`,pointing:null,source_page:33,note:`ABSENT`},{id:`a1-02`,movement:`antiphon_1`,speaker:`choir`,text:`Bless the Lord, O my soul! Blessèd art Thou, O Lord!`,pointing:null,source_page:33,note:`ABSENT`},{id:`a1-03`,movement:`antiphon_1`,speaker:`choir`,text:`Bless the Lord, O my soul! And all that is within me, bless His Holy Name!`,pointing:null,source_page:33,note:`ABSENT`},{id:`a1-04`,movement:`antiphon_1`,speaker:`choir`,text:`Bless the Lord, O my soul! And forget not all His benefits!`,pointing:null,source_page:33,note:`ABSENT`},{id:`a1-05`,movement:`antiphon_1`,speaker:`choir`,text:`Who forgives all your iniquity, Who heals all your diseases!`,pointing:null,source_page:33,note:`ABSENT`},{id:`a1-06`,movement:`antiphon_1`,speaker:`choir`,text:`The Lord is compassionate and merciful, long suffering and of great goodness!`,pointing:null,source_page:34,note:`ABSENT`},{id:`a1-07`,movement:`antiphon_1`,speaker:`choir`,text:`Bless the Lord, O my soul! Blessèd art Thou, O Lord!`,pointing:null,source_page:34,note:`Refrain repeat, as printed — not assumed to repeat after every verse (verses a1-03..a1-05 print with no refrain between them).`},{id:`a1-footnote`,movement:`antiphon_1`,speaker:`rubric`,text:`On Feast Days, special Antiphons are sung. See Appendices VI and VII.`,pointing:null,source_page:33,note:`Footnote tied to the '*' on a1-heading.`},{id:`ll1-heading`,movement:`litany_small_1`,speaker:`heading`,text:`LITTLE LITANY`,pointing:null,source_page:34,note:`ABSENT`},{id:`ll1-01`,movement:`litany_small_1`,speaker:`rubric`,text:`At the completion of the First Antiphon, the deacon, takes his accustomed place, and, having made a reverence, says:`,pointing:null,source_page:34,note:`ABSENT`},{id:`ll1-02`,movement:`litany_small_1`,speaker:`deacon`,mode:null,text:`Again and again in peace let us pray to the Lord.`,pointing:null,source_page:34,note:`ABSENT`},{id:`ll1-03`,movement:`litany_small_1`,speaker:`choir`,text:`Lord, have mercy.`,pointing:null,source_page:34,note:`ABSENT`},{id:`ll1-04`,movement:`litany_small_1`,speaker:`deacon`,mode:null,text:`Help us, save us, have mercy on us, and keep us, O God, by Thy grace.`,pointing:null,source_page:34,note:`ABSENT`},{id:`ll1-05`,movement:`litany_small_1`,speaker:`choir`,text:`Lord, have mercy.`,pointing:null,source_page:34,note:`ABSENT`},{id:`ll1-06`,movement:`litany_small_1`,speaker:`deacon`,mode:null,text:`Commemorating our most holy, most pure, most blessèd and glorious Lady Theotokos and Ever-Virgin Mary with all the saints, let us commend ourselves and each other, and all our life unto Christ our God.`,pointing:null,source_page:34,note:`ABSENT`},{id:`ll1-07`,movement:`litany_small_1`,speaker:`choir`,text:`To Thee, O Lord.`,pointing:null,source_page:34,note:`ABSENT`},{id:`ll1-08`,movement:`litany_small_1`,speaker:`rubric`,text:`Likewise during the Litany, the priest quietly recites the prayer of the Second Antiphon:`,pointing:null,source_page:34,note:`ABSENT`},{id:`ll1-09`,movement:`litany_small_1`,speaker:`priest`,mode:`quiet`,text:`O Lord our God, save Thy people and bless Thine inheritance. Preserve the fullness of Thy Church. Sanctify those who love the beauty of Thy house; glorify them in return by Thy divine power, and forsake us not who put our hope in Thee.`,pointing:null,source_page:34,note:`mode:quiet confirmed by both rubric wording and italic typesetting.`},{id:`ll1-10`,movement:`litany_small_1`,speaker:`heading`,text:`Exclamation:`,pointing:null,source_page:34,note:`ABSENT`},{id:`ll1-11`,movement:`litany_small_1`,speaker:`priest`,mode:`aloud`,text:`For Thine is the dominion, and Thine is the kingdom, and the power, and the glory: of the Father, and of the Son, and of the Holy Spirit, now and ever, and unto ages of ages.`,pointing:null,source_page:34,note:`Text spans the page break (34→35) in source; encoded as one continuous unit. mode:aloud confirmed by 'Exclamation:' cue + upright typesetting.`},{id:`ll1-12`,movement:`litany_small_1`,speaker:`choir`,text:`Amen.`,pointing:null,source_page:35,note:`ABSENT`},{id:`a2-heading`,movement:`antiphon_2`,speaker:`heading`,text:`SECOND ANTIPHON *`,pointing:null,source_page:35,note:`Asterisk ties to footnote a2-footnote.`},{id:`a2-01`,movement:`antiphon_2`,speaker:`rubric`,text:`And the Second Antiphon is sung in like manner by the choir while the deacon again, stands before the icon of Christ.`,pointing:null,source_page:35,note:`ABSENT`},{id:`a2-02`,movement:`antiphon_2`,speaker:`choir`,text:`Glory to the Father, and to the Son, and to the Holy Spirit.`,pointing:null,source_page:35,note:`ABSENT`},{id:`a2-03`,movement:`antiphon_2`,speaker:`choir`,text:`Praise the Lord, O my soul! I will praise the Lord as long as I live; I will sing praises to my God while I have being.`,pointing:null,source_page:35,note:`ABSENT`},{id:`a2-04`,movement:`antiphon_2`,speaker:`choir`,text:`Put not your trust in princes, in sons of men, in whom there is no salvation.`,pointing:null,source_page:35,note:`ABSENT`},{id:`a2-05`,movement:`antiphon_2`,speaker:`choir`,text:`When his breath departs, he returns to his earth; on that very day his plans perish.`,pointing:null,source_page:35,note:`ABSENT`},{id:`a2-06`,movement:`antiphon_2`,speaker:`choir`,text:`The Lord will reign forever; Thy God, O Zion, to all generations.`,pointing:null,source_page:35,note:`ABSENT`},{id:`a2-07`,movement:`antiphon_2`,speaker:`choir`,text:`Now and ever, and unto ages of ages. Amen.`,pointing:null,source_page:35,note:`ABSENT`},{id:`a2-08`,movement:`antiphon_2`,speaker:`choir`,text:`Only-begotten Son and Immortal Word of God, Who for our salvation didst will to be incarnate of the Holy Theotokos and Ever-Virgin Mary, Who without change didst become man and wast crucified, O Christ our God, trampling down death by death, Who art One of the Holy Trinity, glorified with the Father and the Holy Spirit, save us!`,pointing:null,source_page:35,note:`Liturgically this is the fixed hymn 'Ho Monogenes,' distinct from the Psalm 102/103 antiphon verses preceding it — but the source prints no separate heading for it, so it is NOT split into its own movement. Flagged here for visibility, not acted on.`},{id:`a2-footnote`,movement:`antiphon_2`,speaker:`rubric`,text:`On Feast Days, special Antiphons are sung. See Appendices VI and VII.`,pointing:null,source_page:35,note:`Same footnote text as a1-footnote, reprinted verbatim at its own point of occurrence rather than deduplicated.`},{id:`ll2-heading`,movement:`litany_small_2`,speaker:`heading`,text:`LITTLE LITANY`,pointing:null,source_page:36,note:`ABSENT`},{id:`ll2-01`,movement:`litany_small_2`,speaker:`deacon`,mode:null,text:`Again and again in peace let us pray to the Lord.`,pointing:null,source_page:36,note:`ABSENT`},{id:`ll2-02`,movement:`litany_small_2`,speaker:`choir`,text:`Lord, have mercy.`,pointing:null,source_page:36,note:`ABSENT`},{id:`ll2-03`,movement:`litany_small_2`,speaker:`deacon`,mode:null,text:`Help us, save us, have mercy on us, and keep us, O God, by Thy grace.`,pointing:null,source_page:36,note:`ABSENT`},{id:`ll2-04`,movement:`litany_small_2`,speaker:`choir`,text:`Lord, have mercy.`,pointing:null,source_page:36,note:`ABSENT`},{id:`ll2-05`,movement:`litany_small_2`,speaker:`deacon`,mode:null,text:`Commemorating our most holy, most pure, most blessèd and glorious Lady Theotokos and Ever-Virgin Mary with all the saints, let us commend ourselves and each other, and all our life unto Christ our God.`,pointing:null,source_page:36,note:`ABSENT`},{id:`ll2-06`,movement:`litany_small_2`,speaker:`choir`,text:`To Thee, O Lord.`,pointing:null,source_page:36,note:`ABSENT`},{id:`ll2-07`,movement:`litany_small_2`,speaker:`rubric`,text:`Likewise during the Litany, the priest quietly recites the prayer of the Third Antiphon:`,pointing:null,source_page:36,note:`ABSENT`},{id:`ll2-08`,movement:`litany_small_2`,speaker:`priest`,mode:`quiet`,text:`O Thou Who hast given us grace to make our common and united supplication unto Thee, and promised that when two or three are gathered together in Thy Name Thou wouldst grant their requests: Fulfill now, O Lord, the petitions of Thy servants as may be expedient for them: granting us in this world the knowledge of Thy truth, and in the world to come, life everlasting.`,pointing:null,source_page:36,note:`mode:quiet confirmed by rubric wording + italic typesetting.`},{id:`ll2-09`,movement:`litany_small_2`,speaker:`heading`,text:`Exclamation:`,pointing:null,source_page:36,note:`ABSENT`},{id:`ll2-10`,movement:`litany_small_2`,speaker:`priest`,mode:`aloud`,text:`For Thou art a good God and lovest mankind, and unto Thee do we send up glory: to the Father, and to the Son, and to the Holy Spirit, now and ever, and unto ages of ages.`,pointing:null,source_page:36,note:`ABSENT`},{id:`ll2-11`,movement:`litany_small_2`,speaker:`choir`,text:`Amen.`,pointing:null,source_page:36,note:`ABSENT`},{id:`ll2-12`,movement:`litany_small_2`,speaker:`rubric`,text:`The Royal Doors, if closed, are now opened.`,pointing:null,source_page:36,note:`ABSENT`},{id:`a3-heading`,movement:`antiphon_3`,speaker:`heading`,text:`THIRD ANTIPHON *`,pointing:null,source_page:37,note:`Asterisk ties to footnote a3-footnote.`},{id:`a3-01`,movement:`antiphon_3`,speaker:`rubric`,text:`The Third Antiphon, or the Beatitudes with troparia (if Sunday or as appointed in the Menaion), is sung. At Glory... (or Blessèd are the peacemakers... if the Beatitudes are sung without troparia), the priest and deacon reverence the Holy Table as usual, and the deacon receives the Holy Gospel from the priest kissing his right hand. Preceded by the servers with lighted candles, they go around the Holy Table, and through the north door make the Little Entrance.`,pointing:null,source_page:37,note:`Dual-purpose rubric: describes both the antiphon's variable content AND that the Little Entrance procession happens concurrently.`},{id:`a3-02`,movement:`antiphon_3`,speaker:`choir`,text:`In Thy Kingdom remember us, O Lord, when Thou comest in Thy Kingdom.`,pointing:null,source_page:37,note:`ABSENT`},{id:`a3-03`,movement:`antiphon_3`,speaker:`choir`,text:`Blessèd are the poor in spirit, for theirs is the Kingdom of Heaven. {{(on 12)}}`,pointing:null,source_page:37,note:`'(on 12)' is a troparia-insertion count, printed in red — reuses the {{...}} inline marker from spec v4.`},{id:`a3-04`,movement:`antiphon_3`,speaker:`choir`,text:`Blessèd are those who mourn, for they shall be comforted.`,pointing:null,source_page:37,note:`ABSENT`},{id:`a3-05`,movement:`antiphon_3`,speaker:`choir`,text:`Blessèd are the meek, for they shall inherit the earth. {{(on 10)}}`,pointing:null,source_page:37,note:`ABSENT`},{id:`a3-06`,movement:`antiphon_3`,speaker:`choir`,text:`Blessèd are those who hunger and thirst after righteousness, for they shall be filled.`,pointing:null,source_page:37,note:`ABSENT`},{id:`a3-07`,movement:`antiphon_3`,speaker:`choir`,text:`Blessèd are the merciful, for they shall obtain mercy. {{(on 8)}}`,pointing:null,source_page:37,note:`ABSENT`},{id:`a3-08`,movement:`antiphon_3`,speaker:`choir`,text:`Blessèd are the pure in heart, for they shall see God.`,pointing:null,source_page:37,note:`ABSENT`},{id:`a3-09`,movement:`antiphon_3`,speaker:`choir`,text:`Blessèd are the peacemakers for they shall be called the sons of God.`,pointing:null,source_page:37,note:`ABSENT`},{id:`a3-10`,movement:`antiphon_3`,speaker:`choir`,text:`Blessèd are those who are persecuted for righteousness' sake, for theirs is the Kingdom of Heaven.`,pointing:null,source_page:37,note:`ABSENT`},{id:`a3-11`,movement:`antiphon_3`,speaker:`choir`,text:`Blessèd are you when men shall revile you and persecute you, and shall say all manner of evil against you falsely for my sake.`,pointing:null,source_page:37,note:`ABSENT`},{id:`a3-12`,movement:`antiphon_3`,speaker:`choir`,text:`Rejoice and be exceedingly glad, for great is your reward in Heaven. {{(Glory...)}}`,pointing:null,source_page:37,note:`'(Glory...)' marks where the Trinitarian doxology insertion begins when troparia follow.`},{id:`a3-footnote`,movement:`antiphon_3`,speaker:`rubric`,text:`On Feast Days, special Antiphons are sung. See App. VI and VII.`,pointing:null,source_page:37,note:`ABSENT`},{id:`le-heading`,movement:`little_entrance`,speaker:`heading`,text:`LITTLE ENTRANCE`,pointing:null,source_page:38,note:`ABSENT`},{id:`le-01`,movement:`little_entrance`,speaker:`deacon`,mode:`quiet`,cue:`(with a lowered voice)`,text:`Let us pray to the Lord.`,pointing:null,source_page:38,note:`Printed inline annotation is '(with a lowered voice)', not '(quietly)' — treated as mode:quiet; exact source wording preserved and rendered verbatim as the cue, not normalized.`},{id:`le-02`,movement:`little_entrance`,speaker:`priest`,mode:`quiet`,cue:`(silently recites the Prayer of the Entrance)`,text:`O Master, Lord our God, Who hast appointed in heaven orders and hosts of angels and archangels for the service of Thy glory: Grant that with our entrance there may be an entrance of holy angels, serving with us and glorifying Thy goodness. For unto Thee are due all glory, honor, and worship: to the Father, and to the Son, and to the Holy Spirit, now and ever, and unto ages of ages. Amen.`,pointing:null,source_page:38,note:`Printed inline annotation is '(silently recites the Prayer of the Entrance)' — treated as mode:quiet, exact wording preserved and rendered verbatim as the cue.`},{id:`le-03`,movement:`little_entrance`,speaker:`rubric`,text:`Standing before the Royal Doors and leaning the Holy Gospel upon his left shoulder, the deacon holding his orarion with three fingers of his right hand points towards the east through the open Doors and says to the priest:`,pointing:null,source_page:38,note:`ABSENT`},{id:`le-04`,movement:`little_entrance`,speaker:`deacon`,mode:null,text:`Bless, Master, the Holy Entrance.`,pointing:null,source_page:38,note:`ABSENT`},{id:`le-05`,movement:`little_entrance`,speaker:`rubric`,text:`The priest gives the blessing, saying:`,pointing:null,source_page:38,note:`ABSENT`},{id:`le-06`,movement:`little_entrance`,speaker:`priest`,mode:null,text:`Blessèd is the entrance of Thy holy ones always, now and ever, and unto ages of ages.`,pointing:null,source_page:38,note:`ABSENT`},{id:`le-07`,movement:`little_entrance`,speaker:`rubric`,text:`The deacon presents the Holy Gospel to the priest who then kisses the Gospel and places his right hand on the side of the book so the deacon can kiss it. Once the Third Antiphon is concluded, the deacon, stands before the open Doors facing east and exclaims in a great voice as he elevates the Book in a crosswise fashion:`,pointing:null,source_page:38,note:`ABSENT`},{id:`le-08`,movement:`little_entrance`,speaker:`deacon`,mode:`aloud`,text:`Wisdom! Let us attend!`,pointing:null,source_page:38,note:`ABSENT`},{id:`le-09`,movement:`little_entrance`,speaker:`rubric`,text:`The deacon now enters the sanctuary, returns the Holy Gospel to the Holy Table and kisses it as the choir sings the Entrance Hymn, Come let us worship.... The priest, having kissed the small icons of Christ and the Theotokos on either side of the Royal doors, reenters the sanctuary.`,pointing:null,source_page:38,note:`Rubric itself quotes the hymn's opening words as a cross-reference; the actual sung text is captured separately in le-10.`},{id:`le-10`,movement:`little_entrance`,speaker:`choir`,text:`Come, let us worship and fall down before Christ. O Son of God, ___, save us, who sing to Thee: Alleluia!`,pointing:null,source_page:38,note:`RESOLVED (spec v8) — the '___' selects among fixed day-type variants, given verbatim in le-11. This module encodes exactly what the source page prints; resolving which variant applies is deliberately left to whatever service integrates this data into the Hours tool, not solved here.`},{id:`le-11`,movement:`little_entrance`,speaker:`rubric`,text:`SUNDAYS: Who didst rise from the dead, / WEEKDAYS: Who art wonderous in the saints, / FEASTS OF THE THEOTOKOS: Through the prayers of the Theotokos, / (OTHER FEASTS): See Appendices VI and VII.`,pointing:null,source_page:39,note:`Verbatim capture of le-10's day-type variant options, printed as a reference table rather than the {{...}} inline-alternative convention (these are complete mutually-exclusive substitutions, not a single editorial aside).`},{id:`tk-01`,movement:`troparia_kontakia`,speaker:`rubric`,text:`The choir now sings the appointed Troparia and Kontakia (See Appendices V—VIII) while the priest recites quietly the Prayer of the Thrice-Holy:`,pointing:null,source_page:39,note:`Movement boundary confirmed under the ratified v5 rule — content/rubric-derived, not heading-derived. per v5.`},{id:`tk-02`,movement:`troparia_kontakia`,speaker:`priest`,mode:`quiet`,text:`O Holy God, Who resteth in Thy Holy Place; Who art hymned by the Seraphim with the Thrice-Holy cry, and glorified by the Cherubim, and worshipped by every heavenly power; Who out of nothing hast brought all things into being: Who hast created man after Thine own image and likeness, and hast adorned him with Thine every gift; Who givest to him who asks wisdom and understanding; Who dost not despise the sinner, but instead hast appointed repentance unto salvation; Who hast vouchsafed us, Thy humble and unworthy servants, even in this hour to stand before the glory of Thy holy altar, and to offer worship and praise which are due unto Thee. Thyself, O Master, accept even from the mouths of us sinners the Thrice-Holy hymn, and visit us in Thy goodness. Forgive us every transgression, both voluntary and involuntary. Sanctify our souls and bodies, and enable us to serve Thee in holiness all the days of our life. Though the intercessions of the Holy Theotokos and all the saints who from the beginning of the world have been well-pleasing to Thee.`,pointing:null,source_page:39,note:`mode:quiet confirmed by rubric wording + italic typesetting. Ends mid-clause as printed — grammar completes in the Exclamation (tk-08), retained verbatim rather than smoothed.`},{id:`tk-03`,movement:`troparia_kontakia`,speaker:`rubric`,text:`At Now and ever... and the last Kontakion, the deacon kisses the corner of the Holy Table, and holding his orarion to receive a blessing, approaches and reverences the High Place saying:`,pointing:null,source_page:39,note:`Text spans the page break (39→40) in source; encoded as one continuous unit.`},{id:`tk-04`,movement:`troparia_kontakia`,speaker:`deacon`,mode:null,text:`Bless, Master, the time of the Thrice-Holy.`,pointing:null,source_page:40,note:`ABSENT`},{id:`tk-05`,movement:`troparia_kontakia`,speaker:`rubric`,text:`Blessing him, the priest awaits the end of the Kontakion. The deacon comes out through the Royal Doors and stands before the icon of Christ. When the Kontakion is completed, he exclaims:`,pointing:null,source_page:40,note:`ABSENT`},{id:`tk-06`,movement:`troparia_kontakia`,speaker:`deacon`,mode:null,text:`Let us pray to the Lord!`,pointing:null,source_page:40,note:`ABSENT`},{id:`tk-07`,movement:`troparia_kontakia`,speaker:`choir`,text:`Lord have mercy.`,pointing:null,source_page:40,note:`ABSENT`},{id:`tk-08`,movement:`troparia_kontakia`,speaker:`priest`,mode:`aloud`,text:`For Holy art Thou, O our God, and unto Thee do we send up glory: to the Father, and to the Son, and to the Holy Spirit, now and ever...`,pointing:null,source_page:40,note:`No 'Exclamation:' cue label this time (unlike prior instances) — mode:aloud assigned on upright typesetting + liturgical function. Trails into ellipsis, resumed by the deacon in tk-13.`},{id:`tk-09`,movement:`troparia_kontakia`,speaker:`rubric`,text:`During the priest's exclamation, he points with his orarion to the icon of Christ and then, at its conclusion exclaims antiphonally with the choir:`,pointing:null,source_page:40,note:`ABSENT`},{id:`tk-10`,movement:`troparia_kontakia`,speaker:`deacon`,mode:null,text:`O Lord, save the pious!`,pointing:null,source_page:40,note:`Source prints this and tk-11 as one line under a single 'DEACON:' label ('O Lord, save the pious! / And hear us!'). Split into two units because the preceding rubric (tk-09) explicitly states the deacon 'exclaims antiphonally with the choir' — not inferred from the slash alone.`},{id:`tk-11`,movement:`troparia_kontakia`,speaker:`choir`,text:`And hear us!`,pointing:null,source_page:40,note:`See tk-10 note.`},{id:`tk-12`,movement:`troparia_kontakia`,speaker:`rubric`,text:`Then, stepping into the middle of the amvon, and leading with his orarion from left to right while turning and facing the worshipping congregation, he completes the exclamation in a great voice:`,pointing:null,source_page:40,note:`ABSENT`},{id:`tk-13`,movement:`troparia_kontakia`,speaker:`deacon`,mode:null,text:`...And unto ages of ages!`,pointing:null,source_page:40,note:`Completes the priest's exclamation begun in tk-08 — one doxology split across two speakers with ritual action between, encoded verbatim including both ellipses.`},{id:`tk-14`,movement:`troparia_kontakia`,speaker:`rubric`,text:`And the deacon enters the sanctuary, reverences the High Place, bows to the priest, and returns to his usual place. If there is no deacon, the priest completes: ...and unto ages of ages!`,pointing:null,source_page:40,note:`Conditional alternate (no-deacon case) retained verbatim; not modeled as branching logic here, just captured as printed.`},{id:`tk-15`,movement:`troparia_kontakia`,speaker:`choir`,text:`Amen.`,pointing:null,source_page:40,note:`ABSENT`},{id:`tk-16`,movement:`troparia_kontakia`,speaker:`rubric`,text:`The choir now sings the Trisagion Hymn while the priest and deacon quietly recite the Trisagion in the sanctuary, making three reverences before the Holy Table, as usual.`,pointing:null,source_page:40,note:`ABSENT`},{id:`tr-heading`,movement:`trisagion`,speaker:`heading`,text:`TRISAGION *`,pointing:null,source_page:40,note:`Asterisk ties to footnote tr-footnote.`},{id:`tr-01`,movement:`trisagion`,speaker:`choir`,text:`Holy God! Holy Mighty! Holy Immortal! Have mercy on us. {{(3)}}`,pointing:null,source_page:40,note:`'(3)' is a repeat-count instruction, printed small in red — reuses the {{...}} inline marker.`},{id:`tr-footnote`,movement:`trisagion`,speaker:`rubric`,text:`On certain Feast Days, this is replaced by another hymn. See Appendices VI and VII.`,pointing:null,source_page:40,note:`ABSENT`},{id:`tr-02`,movement:`trisagion`,speaker:`choir`,text:`Glory to the Father, and to the Son, and to the Holy Spirit, now and ever, and unto ages of ages. Amen.`,pointing:null,source_page:41,note:`Continuation of the Trisagion's troped form — no CHOIR: label reprinted (tr-02..tr-04).`},{id:`tr-03`,movement:`trisagion`,speaker:`choir`,text:`Holy Immortal! Have mercy on us.`,pointing:null,source_page:41,note:`ABSENT`},{id:`tr-04`,movement:`trisagion`,speaker:`choir`,text:`Holy God! Holy Mighty! Holy Immortal! Have mercy on us.`,pointing:null,source_page:41,note:`ABSENT`},{id:`tr-05`,movement:`trisagion`,speaker:`rubric`,text:`And the deacon says to the priest:`,pointing:null,source_page:41,note:`ABSENT`},{id:`tr-06`,movement:`trisagion`,speaker:`deacon`,mode:`quiet`,text:`Command, Master!`,pointing:null,source_page:41,note:`Private exchange between clergy — mode:quiet per italic typesetting (no explicit rubric wording this time; typographic signal alone).`},{id:`tr-07`,movement:`trisagion`,speaker:`rubric`,text:`As they go to the High Place, the priest says:`,pointing:null,source_page:41,note:`ABSENT`},{id:`tr-08`,movement:`trisagion`,speaker:`priest`,mode:`quiet`,text:`Blessèd is He that comes in the Name of the Lord.`,pointing:null,source_page:41,note:`mode:quiet per italic typesetting.`},{id:`tr-09`,movement:`trisagion`,speaker:`deacon`,mode:`quiet`,text:`Bless, Master, the High Place.`,pointing:null,source_page:41,note:`mode:quiet per italic typesetting.`},{id:`tr-10`,movement:`trisagion`,speaker:`priest`,mode:`quiet`,text:`Blessèd art Thou on the Throne of the glory of Thy Kingdom, Who sittest upon the Cherubim; always, now and ever, and unto ages of ages.`,pointing:null,source_page:41,note:`mode:quiet per italic typesetting.`},{id:`pk-heading`,movement:`prokeimenon`,speaker:`heading`,text:`EPISTLE READING`,pointing:null,source_page:41,note:`Covers both prokeimenon and epistle content per the source; attached here since it immediately precedes the Prokeimenon dialogue.`},{id:`pk-01`,movement:`prokeimenon`,speaker:`rubric`,text:`The priest then takes his place on the south side of the High Place, the center being reserved for the Bishop, while the deacon, having come from the High Place to stand at the Royal Doors faces the congregation, and says:`,pointing:null,source_page:41,note:`ABSENT`},{id:`pk-02`,movement:`prokeimenon`,speaker:`deacon`,mode:null,text:`Let us attend!`,pointing:null,source_page:41,note:`ABSENT`},{id:`pk-03`,movement:`prokeimenon`,speaker:`priest`,mode:null,text:`Peace be unto all!`,pointing:null,source_page:41,note:`ABSENT`},{id:`pk-04`,movement:`prokeimenon`,speaker:`reader`,text:`And to your spirit!`,pointing:null,source_page:41,note:`ABSENT`},{id:`pk-05`,movement:`prokeimenon`,speaker:`deacon`,mode:null,text:`Wisdom!`,pointing:null,source_page:41,note:`ABSENT`},{id:`pk-06`,movement:`prokeimenon`,speaker:`reader`,text:`The Prokeimenon in the ___ Tone:`,pointing:null,source_page:41,note:`Blank for the tone number — same convention as other name/number blanks.`},{id:`pk-07`,movement:`prokeimenon`,speaker:`rubric`,text:`The reader and choir antiphonally chant the Prokeimenon from the Psalms of David, and its verse(s) (See Appendices V—VIII).`,pointing:null,source_page:41,note:`ABSENT`},{id:`ep-01`,movement:`epistle`,speaker:`deacon`,mode:null,text:`Wisdom!`,pointing:null,source_page:42,note:`Movement boundary confirmed under the ratified v5 rule — content-derived (no heading here); per v5.`},{id:`ep-02`,movement:`epistle`,speaker:`reader`,text:`The reading from...`,pointing:null,source_page:42,note:`ABSENT`},{id:`ep-03`,movement:`epistle`,speaker:`rubric`,text:`(the Acts of the Holy Apostles). (...the Epistle of the holy Apostle Paul to the ___). (...the {{[General]}} Epistle of Saint ___).`,pointing:null,source_page:42,note:`Three mutually-exclusive template completions for the reader's opening line, printed in red as editorial guidance — exactly one is used depending on the day's appointed Epistle. Encoded as one rubric-style options list rather than three separate reader lines, since these are complete alternate continuations, not a single aside within one fixed sentence. The '[General]' bracket within the third option is itself a red inline aside — wrapped in {{...}} per the convention (fixed retroactively per Bill's confirmation; originally left unwrapped — see spec v9).`},{id:`ep-04`,movement:`epistle`,speaker:`deacon`,mode:null,text:`Let us attend!`,pointing:null,source_page:42,note:`ABSENT`},{id:`ep-05`,movement:`epistle`,speaker:`rubric`,text:`The reader chants the appointed Epistle pericope while the deacon, having received the blessing, censes the Holy Table round about, the entire sanctuary, and the priest.`,pointing:null,source_page:42,note:`ABSENT`},{id:`ep-06`,movement:`epistle`,speaker:`rubric`,text:`The priest, meanwhile, standing at the High Place, quietly reads the Prayer before the Gospel:`,pointing:null,source_page:42,note:`ABSENT`},{id:`ep-07`,movement:`epistle`,speaker:`priest`,mode:`quiet`,text:`Illumine our hearts, O Master Who lovest mankind, with the pure light of Thy divine knowledge. Open the eyes of our mind to the understanding of Thy Gospel teachings. Implant also in us the fear of Thy blessèd commandments, that trampling down all carnal desires, we may enter upon a spiritual manner of living, both thinking and doing such things as are well-pleasing unto Thee. For Thou art the illumination of our souls and bodies, O Christ our God, and unto Thee do we send up glory, together with Thy Father, Who is from everlasting, and Thine All-Holy, Good, and Life-creating Spirit, now and ever, and unto ages of ages. Amen.`,pointing:null,source_page:42,note:`mode:quiet per rubric wording + italic typesetting.`},{id:`ep-08`,movement:`epistle`,speaker:`rubric`,text:`Upon the completion of the Epistle reading, the priest blesses the reader with the Sign of the Cross, saying:`,pointing:null,source_page:42,note:`ABSENT`},{id:`ep-09`,movement:`epistle`,speaker:`priest`,mode:null,text:`Peace be unto you, reader.`,pointing:null,source_page:42,note:`ABSENT`},{id:`ep-10`,movement:`epistle`,speaker:`reader`,text:`And to your spirit.`,pointing:null,source_page:42,note:`ABSENT`},{id:`al-01`,movement:`alleluia`,speaker:`deacon`,mode:null,text:`Wisdom!`,pointing:null,source_page:42,note:`Movement boundary confirmed under the ratified v5 rule — content-derived; per v5.`},{id:`al-02`,movement:`alleluia`,speaker:`reader`,text:`In the ___ tone, Alleluia! Alleluia! Alleluia!`,pointing:null,source_page:42,note:`Blank for tone number, same convention.`},{id:`al-03`,movement:`alleluia`,speaker:`rubric`,text:`The reader chants the Alleluia Verses (See Appendices V—VIII). After each one, the choir repeats the Alleluia.`,pointing:null,source_page:42,note:`ABSENT`},{id:`go-heading`,movement:`gospel`,speaker:`heading`,text:`GOSPEL READING`,pointing:null,source_page:43,note:`ABSENT`},{id:`go-01`,movement:`gospel`,speaker:`rubric`,text:`Having returned the censer to its place during the singing of the Alleluia and its verses, the deacon receives from the priest the book of the Holy Gospels holding the orarion in his right hand, and brings it to the place appointed, preceded by candles. Now, holding it upright on the lectern, he says:`,pointing:null,source_page:43,note:`ABSENT`},{id:`go-02`,movement:`gospel`,speaker:`deacon`,mode:null,text:`Bless, Master, him who proclaims the good tidings of the holy Apostle and Evangelist ___ {{(Matthew, Mark, Luke or John the Theologian)}}.`,pointing:null,source_page:43,note:`Blank + red inline alternative list — reuses the {{...}} convention for the parenthetical option list.`},{id:`go-03`,movement:`gospel`,speaker:`rubric`,text:`The priest blesses him with the Sign of the Cross, saying:`,pointing:null,source_page:43,note:`ABSENT`},{id:`go-04`,movement:`gospel`,speaker:`priest`,mode:null,text:`May God, through the prayers of the holy, glorious, and all-laudable Apostle and Evangelist ___, enable you to proclaim the good tidings with great power, to the fulfillment of the Gospel of His belovèd Son, our Lord Jesus Christ.`,pointing:null,source_page:43,note:`Blank for evangelist name, same convention.`},{id:`go-05`,movement:`gospel`,speaker:`deacon`,mode:null,text:`Amen.`,pointing:null,source_page:43,note:`ABSENT`},{id:`go-06`,movement:`gospel`,speaker:`priest`,mode:null,text:`Wisdom! Let us attend. Let us hear the Holy Gospel.`,pointing:null,source_page:43,note:`ABSENT`},{id:`go-07`,movement:`gospel`,speaker:`heading`,text:`Also:`,pointing:null,source_page:43,note:`Exact triggering condition not stated on this page (e.g. hierarchical vs. presbyteral service) — flagged rather than guessed.`},{id:`go-08`,movement:`gospel`,speaker:`priest`,mode:null,text:`Peace be unto all.`,pointing:null,source_page:43,note:`ABSENT`},{id:`go-09`,movement:`gospel`,speaker:`choir`,text:`And to your spirit.`,pointing:null,source_page:43,note:`ABSENT`},{id:`go-10`,movement:`gospel`,speaker:`rubric`,text:`Then, placing his orarion on the lectern, and laying the book of the Holy Gospels down upon it, the deacon says:`,pointing:null,source_page:43,note:`ABSENT`},{id:`go-11`,movement:`gospel`,speaker:`deacon`,mode:null,text:`The reading from the Holy Gospel according to Saint ___.`,pointing:null,source_page:43,note:`Blank for evangelist name, same convention.`},{id:`go-12`,movement:`gospel`,speaker:`choir`,text:`Glory to Thee, O Lord, glory to Thee.`,pointing:null,source_page:43,note:`ABSENT`},{id:`go-13`,movement:`gospel`,speaker:`priest`,mode:null,text:`Let us attend!`,pointing:null,source_page:43,note:`Page 43 ends here; Gospel pericope and remainder continue on later pages, not yet provided.`},{id:`go-14`,movement:`gospel`,speaker:`rubric`,text:`The appointed Gospel pericope is chanted by the deacon. Upon its completion, the priest blesses the deacon with the Sign of the Cross, saying:`,pointing:null,source_page:44,note:`ABSENT`},{id:`go-15`,movement:`gospel`,speaker:`priest`,mode:null,text:`Peace be unto you who has proclaimed the good tidings.`,pointing:null,source_page:44,note:`ABSENT`},{id:`go-16`,movement:`gospel`,speaker:`choir`,text:`Glory to Thee, O Lord, glory to Thee.`,pointing:null,source_page:44,note:`ABSENT`},{id:`go-17`,movement:`gospel`,speaker:`rubric`,text:`The deacon, coming back to the Royal Doors, gives the book of the Holy Gospels to the priest who blesses the faithful with it.`,pointing:null,source_page:44,note:`ABSENT`},{id:`go-18`,movement:`gospel`,speaker:`heading`,text:`THE SERMON MAY BE GIVEN HERE`,pointing:null,source_page:44,note:`Printed between two rows of '* * *' separators.`},{id:`lfs-heading`,movement:`litany_fervent_supplication`,speaker:`heading`,text:`LITANY OF FERVENT SUPPLICATION`,pointing:null,source_page:44,note:`ABSENT`},{id:`lfs-01`,movement:`litany_fervent_supplication`,speaker:`deacon`,mode:null,text:`Let us say with all our soul and with all our mind, let us say.`,pointing:null,source_page:44,note:`ABSENT`},{id:`lfs-02`,movement:`litany_fervent_supplication`,speaker:`choir`,text:`Lord, have mercy.`,pointing:null,source_page:44,note:`ABSENT`},{id:`lfs-03`,movement:`litany_fervent_supplication`,speaker:`deacon`,mode:null,text:`O Lord Almighty, the God of our fathers, we pray Thee, hearken and have mercy.`,pointing:null,source_page:44,note:`ABSENT`},{id:`lfs-04`,movement:`litany_fervent_supplication`,speaker:`choir`,text:`Lord, have mercy.`,pointing:null,source_page:44,note:`ABSENT`},{id:`lfs-05`,movement:`litany_fervent_supplication`,speaker:`deacon`,mode:null,text:`Have mercy on us, O God, according to Thy great goodness, we pray Thee, hearken and have mercy.`,pointing:null,source_page:44,note:`ABSENT`},{id:`lfs-06`,movement:`litany_fervent_supplication`,speaker:`choir`,text:`Lord, have mercy. {{(3)}}`,pointing:null,source_page:44,note:`ABSENT`},{id:`lfs-07`,movement:`litany_fervent_supplication`,speaker:`rubric`,text:`The priest now quietly recites the Prayer of Fervent Supplication:`,pointing:null,source_page:44,note:`ABSENT`},{id:`lfs-08`,movement:`litany_fervent_supplication`,speaker:`priest`,mode:`quiet`,text:`O Lord our God, accept this fervent supplication of Thy servants, and have mercy on us according to the multitude of Thy mercies. Send down Thy bounties upon us and upon all Thy people, who await the rich mercy that comes from Thee.`,pointing:null,source_page:44,note:`Printed once at this point though it is prayed silently through several more deacon petitions (lfs-09..lfs-19) before its Exclamation — the book does not reprint the prayer text again.`},{id:`lfs-09`,movement:`litany_fervent_supplication`,speaker:`rubric`,text:`And the Antimension is partly unfolded by the priest: the upper portion is left folded.`,pointing:null,source_page:45,note:`ABSENT`},{id:`lfs-10`,movement:`litany_fervent_supplication`,speaker:`deacon`,mode:null,text:`Again we pray for our lord His Beatitude, the Most blessèd Metropolitan ___, for our lord His Eminence, the Most reverend Archbishop (His Grace, the Right reverend Bishop) ___, for priests, deacons, and all other clergy; and for all our brethren in Christ.`,pointing:null,source_page:45,note:`ABSENT`},{id:`lfs-11`,movement:`litany_fervent_supplication`,speaker:`choir`,text:`Lord, have mercy. {{(3)}}`,pointing:null,source_page:45,note:`ABSENT`},{id:`lfs-12`,movement:`litany_fervent_supplication`,speaker:`deacon`,mode:null,text:`Again we pray for this Country, its President {{(or title of the highest civil authority)}}, for all civil authorities, and for the armed forces.`,pointing:null,source_page:45,note:`ABSENT`},{id:`lfs-13`,movement:`litany_fervent_supplication`,speaker:`choir`,text:`Lord, have mercy. {{(3)}}`,pointing:null,source_page:45,note:`ABSENT`},{id:`lfs-14`,movement:`litany_fervent_supplication`,speaker:`deacon`,mode:null,text:`Again we pray for the blessèd and ever-memorable holy Orthodox Patriarchs; and for the blessèd and ever-memorable founders of this holy temple; and for all our fathers and brethren, the Orthodox departed this life before us, who here and in all the world lie asleep in the Lord.`,pointing:null,source_page:45,note:`ABSENT`},{id:`lfs-15`,movement:`litany_fervent_supplication`,speaker:`choir`,text:`Lord, have mercy. {{(3)}}`,pointing:null,source_page:45,note:`ABSENT`},{id:`lfs-16`,movement:`litany_fervent_supplication`,speaker:`deacon`,mode:null,text:`Again we pray for mercy, life, peace, health, salvation, and visitation for the servants of God ___, and for the pardon and remission of their sins.`,pointing:null,source_page:45,note:`ABSENT`},{id:`lfs-17`,movement:`litany_fervent_supplication`,speaker:`choir`,text:`Lord, have mercy. {{(3)}}`,pointing:null,source_page:45,note:`ABSENT`},{id:`lfs-18`,movement:`litany_fervent_supplication`,speaker:`deacon`,mode:null,text:`Again we pray for those who bring offerings and do good works in this holy and all-venerable temple; for those who labor and those who sing; and for all the people here present, who await Thy great and rich mercy.`,pointing:null,source_page:45,note:`Text spans the page break (45→46) in source; encoded as one continuous unit.`},{id:`lfs-19`,movement:`litany_fervent_supplication`,speaker:`choir`,text:`Lord, have mercy. {{(3)}}`,pointing:null,source_page:46,note:`ABSENT`},{id:`lfs-20`,movement:`litany_fervent_supplication`,speaker:`heading`,text:`Exclamation:`,pointing:null,source_page:46,note:`ABSENT`},{id:`lfs-21`,movement:`litany_fervent_supplication`,speaker:`priest`,mode:`aloud`,text:`For Thou art a merciful God, and lovest mankind, and unto Thee do we send up glory: to the Father, and to the Son, and to the Holy Spirit, now and ever, and unto ages of ages.`,pointing:null,source_page:46,note:`ABSENT`},{id:`lfs-22`,movement:`litany_fervent_supplication`,speaker:`choir`,text:`Amen.`,pointing:null,source_page:46,note:`ABSENT`},{id:`ld-01`,movement:`litany_departed`,speaker:`rubric`,text:`The Litany for the Departed may be recited here, except on Sundays and Feast Days.`,pointing:null,source_page:46,note:`This entire movement is conditional — omitted on Sundays and Feast Days.`},{id:`ld-heading`,movement:`litany_departed`,speaker:`heading`,text:`LITANY FOR THE DEPARTED`,pointing:null,source_page:46,note:`ABSENT`},{id:`ld-02`,movement:`litany_departed`,speaker:`deacon`,mode:null,text:`Have mercy on us, O God, according to Thy great goodness, we pray Thee, hearken and have mercy.`,pointing:null,source_page:46,note:`ABSENT`},{id:`ld-03`,movement:`litany_departed`,speaker:`choir`,text:`Lord, have mercy. {{(3)}}`,pointing:null,source_page:46,note:`ABSENT`},{id:`ld-04`,movement:`litany_departed`,speaker:`deacon`,mode:null,text:`Again we pray for the repose of the soul{{(s)}} of the servant{{(s)}} of God ___, departed this life; and that he {{(she, they)}} may be pardoned all his {{(her, their)}} sins, both voluntary and involuntary.`,pointing:null,source_page:46,note:`Gender/number alternatives printed in red — reuses {{...}} convention for each.`},{id:`ld-05`,movement:`litany_departed`,speaker:`choir`,text:`Lord, have mercy. {{(3)}}`,pointing:null,source_page:46,note:`ABSENT`},{id:`ld-06`,movement:`litany_departed`,speaker:`deacon`,mode:null,text:`That the Lord God will establish his {{(her, their)}} soul{{(s)}} where the just repose.`,pointing:null,source_page:46,note:`ABSENT`},{id:`ld-07`,movement:`litany_departed`,speaker:`choir`,text:`Lord, have mercy. {{(3)}}`,pointing:null,source_page:46,note:`ABSENT`},{id:`ld-08`,movement:`litany_departed`,speaker:`deacon`,mode:null,text:`The mercies of God, the Kingdom of Heaven, and the remission of his {{(her, their)}} sins, let us ask of Christ, the Immortal King and God.`,pointing:null,source_page:46,note:`Text spans the page break (46→47) in source.`},{id:`ld-09`,movement:`litany_departed`,speaker:`choir`,text:`Grant it, O Lord.`,pointing:null,source_page:47,note:`ABSENT`},{id:`ld-10`,movement:`litany_departed`,speaker:`deacon`,mode:null,text:`Let us pray to the Lord.`,pointing:null,source_page:47,note:`ABSENT`},{id:`ld-11`,movement:`litany_departed`,speaker:`choir`,text:`Lord, have mercy.`,pointing:null,source_page:47,note:`ABSENT`},{id:`ld-12`,movement:`litany_departed`,speaker:`priest`,mode:`quiet`,text:`O God of spirits, and of all flesh, Who hast trampled down death and overthrown the devil, and given life to Thy world; do Thou, the same Lord, give rest to the soul{{(s)}} of Thy departed servant{{(s)}} ___, in a place of brightness, a place of refreshment, a place of repose, where all sickness, sighing, and sorrow have fled away. Pardon every transgression, which he {{(she)}} has {{(they have)}} committed, whether by word or deed or thought. For Thou art a good God and lovest mankind; because there is no man who lives yet does not sin; for Thou only art without sin; Thy righteousness is to all eternity; and Thy Word is Truth.`,pointing:null,source_page:47,note:`mode:quiet per italic typesetting.`},{id:`ld-13`,movement:`litany_departed`,speaker:`heading`,text:`Exclamation:`,pointing:null,source_page:47,note:`ABSENT`},{id:`ld-14`,movement:`litany_departed`,speaker:`priest`,mode:`aloud`,text:`For Thou art the Resurrection, the Life, and the Repose of Thy servant{{(s)}} ___, who is {{(are)}} fallen asleep, O Christ our God, and unto Thee do we send up glory, together with Thy Father, Who is from everlasting, and Thine All-Holy, Good, and Life-creating Spirit, now and ever, and unto ages of ages.`,pointing:null,source_page:47,note:`ABSENT`},{id:`ld-15`,movement:`litany_departed`,speaker:`choir`,text:`Amen.`,pointing:null,source_page:47,note:`ABSENT`},{id:`ld-16`,movement:`litany_departed`,speaker:`rubric`,text:`The Royal Doors are now closed and the deacon intones the Litany for the Catechumens.`,pointing:null,source_page:47,note:`ABSENT`},{id:`lc-heading`,movement:`litany_catechumens`,speaker:`heading`,text:`LITANY FOR THE CATECHUMENS`,pointing:null,source_page:48,note:`ABSENT`},{id:`lc-01`,movement:`litany_catechumens`,speaker:`deacon`,mode:null,text:`Pray to the Lord, you catechumens.`,pointing:null,source_page:48,note:`ABSENT`},{id:`lc-02`,movement:`litany_catechumens`,speaker:`choir`,text:`Lord, have mercy.`,pointing:null,source_page:48,note:`ABSENT`},{id:`lc-03`,movement:`litany_catechumens`,speaker:`deacon`,mode:null,text:`Let us, the faithful, pray for the catechumens, that the Lord may have mercy on them.`,pointing:null,source_page:48,note:`ABSENT`},{id:`lc-04`,movement:`litany_catechumens`,speaker:`choir`,text:`Lord, have mercy.`,pointing:null,source_page:48,note:`ABSENT`},{id:`lc-05`,movement:`litany_catechumens`,speaker:`deacon`,mode:null,text:`That He may teach them the word of truth.`,pointing:null,source_page:48,note:`ABSENT`},{id:`lc-06`,movement:`litany_catechumens`,speaker:`choir`,text:`Lord, have mercy.`,pointing:null,source_page:48,note:`ABSENT`},{id:`lc-07`,movement:`litany_catechumens`,speaker:`deacon`,mode:null,text:`That He may reveal to them the Gospel of righteousness.`,pointing:null,source_page:48,note:`ABSENT`},{id:`lc-08`,movement:`litany_catechumens`,speaker:`choir`,text:`Lord, have mercy.`,pointing:null,source_page:48,note:`ABSENT`},{id:`lc-09`,movement:`litany_catechumens`,speaker:`deacon`,mode:null,text:`That He may unite them to His Holy, Catholic, and Apostolic Church.`,pointing:null,source_page:48,note:`ABSENT`},{id:`lc-10`,movement:`litany_catechumens`,speaker:`choir`,text:`Lord, have mercy.`,pointing:null,source_page:48,note:`ABSENT`},{id:`lc-11`,movement:`litany_catechumens`,speaker:`deacon`,mode:null,text:`Help them, save them, have mercy on them, and keep them, O God, by Thy grace.`,pointing:null,source_page:48,note:`ABSENT`},{id:`lc-12`,movement:`litany_catechumens`,speaker:`choir`,text:`Lord, have mercy.`,pointing:null,source_page:48,note:`ABSENT`},{id:`lc-13`,movement:`litany_catechumens`,speaker:`deacon`,mode:null,text:`Bow your heads unto the Lord, you catechumens.`,pointing:null,source_page:48,note:`ABSENT`},{id:`lc-14`,movement:`litany_catechumens`,speaker:`choir`,text:`To Thee, O Lord.`,pointing:null,source_page:48,note:`ABSENT`},{id:`lc-15`,movement:`litany_catechumens`,speaker:`rubric`,text:`During the Litany, the priest quietly recites the Prayer for the Catechumens:`,pointing:null,source_page:48,note:`ABSENT`},{id:`lc-16`,movement:`litany_catechumens`,speaker:`priest`,mode:`quiet`,text:`O Lord our God, Who dwellest on high and regardest the humble of heart; Who hast sent forth as the salvation of the race of men Thine Only-begotten Son and God, our Lord Jesus Christ: Look down upon Thy servants the catechumens, who have bowed their necks before Thee; make them worthy in due time of the laver of regeneration, the remission of sins, and the robe of incorruption. Unite them to Thy Holy, Catholic, and Apostolic Church, and number them with Thy chosen flock.`,pointing:null,source_page:48,note:`Text spans the page break (48→49). Marked with '*' and '(115)' in source: this prayer is replaced in the Liturgy of St. Basil, whose corresponding prayer is found on p.115 of this same book.`},{id:`lc-17`,movement:`litany_catechumens`,speaker:`heading`,text:`Exclamation:`,pointing:null,source_page:49,note:`ABSENT`},{id:`lc-18`,movement:`litany_catechumens`,speaker:`priest`,mode:`aloud`,text:`That with us they may glorify Thine all-honorable and majestic Name: of the Father, and of the Son, and of the Holy Spirit, now and ever, and unto ages of ages.`,pointing:null,source_page:49,note:`ABSENT`},{id:`lc-19`,movement:`litany_catechumens`,speaker:`choir`,text:`Amen.`,pointing:null,source_page:49,note:`ABSENT`},{id:`lc-20`,movement:`litany_catechumens`,speaker:`rubric`,text:`The Antimension is now fully unfolded. The priest makes the Sign of the Cross over it with the sponge, then kisses the sponge and lays it on the right side.`,pointing:null,source_page:49,note:`ABSENT`},{id:`lc-21`,movement:`litany_catechumens`,speaker:`deacon`,mode:null,text:`All catechumens, depart. Depart catechumens. All that are catechumens depart. Let no catechumen remain. Let us, the faithful, again and again in peace pray unto the Lord.`,pointing:null,source_page:49,note:`BORDERLINE — this single deacon utterance both dismisses the catechumens and opens the Litany of the Faithful. Kept in litany_catechumens; litany_faithful_1 is started at the choir's response (lc-22/next). Flagged, not silently decided.`},{id:`lc-22`,movement:`litany_catechumens`,speaker:`choir`,cue:`(slowly)`,text:`Lord, have mercy.`,pointing:null,source_page:49,note:`Printed inline annotation is '(slowly)' — a tempo direction, not an aloud/quiet distinction. Doesn't fit the mode field, so it's carried in its own cue field and rendered verbatim.`},{id:`lf1-01`,movement:`litany_faithful_1`,speaker:`rubric`,text:`And the priest quietly recites the First Prayer of the Faithful:`,pointing:null,source_page:49,note:`Movement boundary confirmed under the ratified v5 rule — content/rubric-derived; no heading is printed anywhere for either Litany of the Faithful in this edition.`},{id:`lf1-02`,movement:`litany_faithful_1`,speaker:`priest`,mode:`quiet`,text:`We thank Thee, O Lord God of Hosts, Who hast accounted us worthy to stand even now before Thy holy altar, and to fall down before Thy compassion for our sins and for the errors of all thy people. And enable us also, whom Thou hast placed in this Thy service, by the power of Thy Holy Spirit, blamelessly and without offence, in the pure witness of our conscience, to call upon Thee at all times and in every place; that hearing us Thou mayest be merciful to us according to the multitude of Thy great goodness.`,pointing:null,source_page:49,note:`Text spans the page break (49→50). Marked with '*' and '(115)' — replaced in the Liturgy of St. Basil, corresponding prayer on p.115.`},{id:`lf1-03`,movement:`litany_faithful_1`,speaker:`deacon`,mode:null,text:`Help us, save us, have mercy on us, and keep us, O God, by Thy grace.`,pointing:null,source_page:50,note:`ABSENT`},{id:`lf1-04`,movement:`litany_faithful_1`,speaker:`choir`,text:`Lord, have mercy.`,pointing:null,source_page:50,note:`ABSENT`},{id:`lf1-05`,movement:`litany_faithful_1`,speaker:`deacon`,mode:null,text:`Wisdom!`,pointing:null,source_page:50,note:`ABSENT`},{id:`lf1-06`,movement:`litany_faithful_1`,speaker:`heading`,text:`Exclamation:`,pointing:null,source_page:50,note:`ABSENT`},{id:`lf1-07`,movement:`litany_faithful_1`,speaker:`priest`,mode:`aloud`,text:`For unto Thee are due all glory, honor, and worship: to the Father, and to the Son, and to the Holy Spirit, now and ever, and unto ages of ages.`,pointing:null,source_page:50,note:`ABSENT`},{id:`lf1-08`,movement:`litany_faithful_1`,speaker:`choir`,text:`Amen.`,pointing:null,source_page:50,note:`ABSENT`},{id:`lf2-01`,movement:`litany_faithful_2`,speaker:`deacon`,mode:null,text:`Again and again in peace let us pray to the Lord.`,pointing:null,source_page:50,note:`Movement boundary confirmed under the ratified v5 rule — content-derived; no heading printed.`},{id:`lf2-02`,movement:`litany_faithful_2`,speaker:`choir`,text:`Lord, have mercy.`,pointing:null,source_page:50,note:`ABSENT`},{id:`lf2-03`,movement:`litany_faithful_2`,speaker:`rubric`,text:`The four following petitions are recited only if a deacon is serving. If the priest serves alone, they are omitted.`,pointing:null,source_page:50,note:`ABSENT`},{id:`lf2-04`,movement:`litany_faithful_2`,speaker:`deacon`,mode:null,text:`For the peace from above and for the salvation of our souls, let us pray to the Lord.`,pointing:null,source_page:50,note:`ABSENT`},{id:`lf2-05`,movement:`litany_faithful_2`,speaker:`choir`,text:`Lord, have mercy.`,pointing:null,source_page:50,note:`ABSENT`},{id:`lf2-06`,movement:`litany_faithful_2`,speaker:`deacon`,mode:null,text:`For the peace of the whole world, for the welfare of the holy churches of God, and for the union of all, let us pray to the Lord.`,pointing:null,source_page:50,note:`Text spans the page break (50→51).`},{id:`lf2-07`,movement:`litany_faithful_2`,speaker:`choir`,text:`Lord, have mercy.`,pointing:null,source_page:51,note:`ABSENT`},{id:`lf2-08`,movement:`litany_faithful_2`,speaker:`deacon`,mode:null,text:`For this holy temple and for those who enter with faith, reverence, and the fear of God, let us pray to the Lord.`,pointing:null,source_page:51,note:`ABSENT`},{id:`lf2-09`,movement:`litany_faithful_2`,speaker:`choir`,text:`Lord, have mercy.`,pointing:null,source_page:51,note:`ABSENT`},{id:`lf2-10`,movement:`litany_faithful_2`,speaker:`deacon`,mode:null,text:`For our deliverance from all affliction, wrath, danger, and necessity, let us pray to the Lord.`,pointing:null,source_page:51,note:`ABSENT`},{id:`lf2-11`,movement:`litany_faithful_2`,speaker:`choir`,text:`Lord, have mercy.`,pointing:null,source_page:51,note:`ABSENT`},{id:`lf2-12`,movement:`litany_faithful_2`,speaker:`deacon`,mode:null,text:`Help us, save us, and have mercy on us, and keep us, O God, by Thy grace.`,pointing:null,source_page:51,note:`ABSENT`},{id:`lf2-13`,movement:`litany_faithful_2`,speaker:`choir`,text:`Lord, have mercy.`,pointing:null,source_page:51,note:`ABSENT`},{id:`lf2-14`,movement:`litany_faithful_2`,speaker:`rubric`,text:`And during the Litany, the priest quietly recites the Second Prayer of the Faithful:`,pointing:null,source_page:51,note:`ABSENT`},{id:`lf2-15`,movement:`litany_faithful_2`,speaker:`priest`,mode:`quiet`,text:`Again and oftentimes we fall down before Thee, O God Who lovest mankind, that looking down upon our petition Thou wouldst cleanse our souls and bodies from all defilement of flesh and spirit; and grant us to stand blameless and without condemnation before Thy holy altar. Grant also to those who pray with us, O God, growth in life and faith and spiritual understanding. Grant them to worship Thee blamelessly with fear and love, and to partake without condemnation of Thy Holy Mysteries, and to be accounted worthy of Thy heavenly Kingdom.`,pointing:null,source_page:51,note:`Marked with '*' and '(116)' — replaced in the Liturgy of St. Basil, corresponding prayer on p.116. Spans the page break (51→52).`},{id:`lf2-16`,movement:`litany_faithful_2`,speaker:`deacon`,mode:null,text:`Wisdom!`,pointing:null,source_page:52,note:`ABSENT`},{id:`lf2-17`,movement:`litany_faithful_2`,speaker:`rubric`,text:`The deacon returns to the sanctuary through the south door.`,pointing:null,source_page:52,note:`Printed inline immediately after 'Wisdom!' on the same line in source; encoded as its own rubric unit.`},{id:`lf2-18`,movement:`litany_faithful_2`,speaker:`heading`,text:`Exclamation:`,pointing:null,source_page:52,note:`ABSENT`},{id:`lf2-19`,movement:`litany_faithful_2`,speaker:`priest`,mode:`aloud`,text:`That guarded always by Thy might we may send up glory unto Thee: to the Father, and to the Son and to the Holy Spirit, now and ever, and unto ages of ages.`,pointing:null,source_page:52,note:`ABSENT`},{id:`lf2-20`,movement:`litany_faithful_2`,speaker:`choir`,text:`Amen.`,pointing:null,source_page:52,note:`ABSENT`},{id:`ch-01`,movement:`cherubic_hymn`,speaker:`rubric`,text:`The Royal Doors are now opened. The deacon takes the censer, receives the priest's blessing, and censes the Holy Table round about, the Holy Gifts, the sanctuary, the iconostasis, the priest, the choir, and the people, reciting to himself Psalm 50 (51) and the penitential troparia, as he may see fit, while the choir solemnly sings the Cherubic Hymn:`,pointing:null,source_page:52,note:`Movement boundary confirmed under the ratified v5 rule — content/rubric-derived; no 'CHERUBIC HYMN' heading is printed anywhere in this edition.`},{id:`ch-02`,movement:`cherubic_hymn`,speaker:`choir`,text:`Let us who mystically represent the Cherubim, and who sing the Thrice-Holy hymn to the Life-creating Trinity, now lay aside all earthly cares.`,pointing:null,source_page:52,note:`ABSENT`},{id:`ch-03`,movement:`cherubic_hymn`,speaker:`rubric`,text:`As the choir sings the Cherubic Hymn, the priest quietly recites the prayer:`,pointing:null,source_page:52,note:`ABSENT`},{id:`ch-04`,movement:`cherubic_hymn`,speaker:`priest`,mode:`quiet`,text:`No one who is bound with the desires and pleasures of the flesh is worthy to approach or draw near or to serve Thee, O King of Glory; for to minister to Thee is great and awesome even to the heavenly powers. Nevertheless through Thine unspeakable and boundless love for mankind, Thou didst become man, yet without change or alteration, and as Ruler of All didst become our High Priest, and didst commit to us the ministry of this liturgical and bloodless sacrifice. For Thou alone, O Lord our God, rulest over those in heaven and on earth; Who art borne on the throne of the Cherubim; Who art Lord of the Seraphim and King of Israel; Who alone art Holy and resteth in Thy Holy Place. Therefore, I entreat Thee Who art good and ready to listen: Look down on me, a sinner, Thine unprofitable servant, and cleanse my soul and my heart from an evil conscience; and by the power of the Holy Spirit enable me, who am endowed with the grace of the priesthood, to stand before this, Thy Holy Table, and perform the Sacred Mystery of Thy Holy and Pure Body and Precious Blood. For I draw near to Thee, and bowing my neck I implore Thee: Do not turn Thy face away from me, nor cast me out from among Thy children; but make me, Thy sinful and unworthy servant, worthy to offer gifts to Thee. For Thou art the One Who Offers and the One Who is Offered, the One Who Receives and the One Who is Received, O Christ our God, and unto Thee do we send up glory, together with Thy Father, Who is from everlasting, and Thine All-Holy, Good and Life-creating Spirit, now and ever, and unto ages of ages. Amen.`,pointing:null,source_page:52,note:`mode:quiet per rubric wording + italic typesetting. Spans the page break (52→53).`},{id:`ch-05`,movement:`cherubic_hymn`,speaker:`rubric`,text:`When the priest finishes reciting the prayer and the deacon his censing, both stand before the Holy Table and recite the Cherubic Hymn three times, bowing after each recitation:`,pointing:null,source_page:53,note:`ABSENT`},{id:`ch-06`,movement:`cherubic_hymn`,speaker:`priest`,mode:null,text:`Let us who mystically represent the Cherubim, and who sing the Thrice-Holy hymn to the Life-creating Trinity, now lay aside all earthly cares.`,pointing:null,source_page:53,note:`Recited three times per ch-05's rubric; printed once here, repetition left as the rubric's instruction rather than tripled in the data.`},{id:`ch-07`,movement:`cherubic_hymn`,speaker:`deacon`,mode:null,text:`That we may receive the King of All, Who comes invisibly upborne by the angelic hosts. Alleluia! Alleluia! Alleluia!`,pointing:null,source_page:53,note:`ABSENT`},{id:`ch-08`,movement:`cherubic_hymn`,speaker:`rubric`,text:`They go before the Table of Oblation; the priest censes the Offering, praying silently to himself:`,pointing:null,source_page:53,note:`ABSENT`},{id:`ch-09`,movement:`cherubic_hymn`,speaker:`priest`,mode:`quiet`,text:`O God, cleanse me, a sinner, and have mercy on me.`,pointing:null,source_page:54,note:`ABSENT`},{id:`ch-10`,movement:`cherubic_hymn`,speaker:`rubric`,text:`The deacon says to the priest:`,pointing:null,source_page:54,note:`ABSENT`},{id:`ch-11`,movement:`cherubic_hymn`,speaker:`deacon`,mode:null,text:`Lift up, Master.`,pointing:null,source_page:54,note:`ABSENT`},{id:`ch-12`,movement:`cherubic_hymn`,speaker:`rubric`,text:`The priest puts the large aer on the deacon's left shoulder saying:`,pointing:null,source_page:54,note:`ABSENT`},{id:`ch-13`,movement:`cherubic_hymn`,speaker:`priest`,mode:null,text:`Lift up your hands to the Holy Place and bless the Lord.`,pointing:null,source_page:54,note:`ABSENT`},{id:`ch-14`,movement:`cherubic_hymn`,speaker:`rubric`,text:`Then, taking the holy diskos, he gives it to the deacon with all heed and reverence. The priest himself takes the chalice in his hands, and they both go forth on the north side, praying, and preceded by servers with lighted candles they make the Great Entrance.`,pointing:null,source_page:54,note:`ABSENT`},{id:`ge-heading`,movement:`great_entrance`,speaker:`heading`,text:`GREAT ENTRANCE`,pointing:null,source_page:54,note:`ABSENT`},{id:`ge-01`,movement:`great_entrance`,speaker:`rubric`,text:`During the Great Entrance, the deacon and the priest pray aloud for the hierarchy and the faithful, according to the accepted formula of the local tradition. After the deacon commemorates the ruling hierarchs, he enters the sanctuary through the Royal Doors, sets himself on his right knee at the southwest corner of the Holy Table holding aloft the diskos while the commemorations are completed. At their conclusion, the priest says:`,pointing:null,source_page:54,note:`ABSENT`},{id:`ge-02`,movement:`great_entrance`,speaker:`priest`,mode:`aloud`,text:`You and all Orthodox Christians, may the Lord God remember in His Kingdom always, now and ever, and unto ages of ages.`,pointing:null,source_page:54,note:`ABSENT`},{id:`ge-03`,movement:`great_entrance`,speaker:`rubric`,text:`The priest re-enters the sanctuary through the Royal Doors as the choir sings:`,pointing:null,source_page:54,note:`ABSENT`},{id:`ge-04`,movement:`great_entrance`,speaker:`choir`,text:`Amen.`,pointing:null,source_page:54,note:`ABSENT`},{id:`ge-05`,movement:`great_entrance`,speaker:`choir`,text:`That we may receive the King of All, Who comes invisibly upborne by the angelic hosts Alleluia! Alleluia! Alleluia!`,pointing:null,source_page:54,note:`Completes the second half of the Cherubic Hymn, sung after the commemorations conclude.`},{id:`ge-06`,movement:`great_entrance`,speaker:`rubric`,text:`As the priest enters through the Royal Doors, the deacon says to him:`,pointing:null,source_page:55,note:`ABSENT`},{id:`ge-07`,movement:`great_entrance`,speaker:`deacon`,mode:null,text:`May the Lord God remember your priesthood in His Kingdom.`,pointing:null,source_page:55,note:`ABSENT`},{id:`ge-08`,movement:`great_entrance`,speaker:`rubric`,text:`And the priest to him:`,pointing:null,source_page:55,note:`ABSENT`},{id:`ge-09`,movement:`great_entrance`,speaker:`priest`,mode:null,text:`May the Lord God remember your diaconate in His Kingdom, always, now and ever, and unto ages of ages.`,pointing:null,source_page:55,note:`ABSENT`},{id:`ge-10`,movement:`great_entrance`,speaker:`rubric`,text:`The priest sets the holy chalice down on the Holy Table, and then, taking the holy diskos from the deacon, sets it down on the Holy Table also, saying:`,pointing:null,source_page:55,note:`ABSENT`},{id:`ge-11`,movement:`great_entrance`,speaker:`priest`,mode:null,text:`The noble Joseph, when he had taken down Thy Most Pure Body from the tree, wrapped it in fine linen and anointed it with spices, and placed it in a new tomb.`,pointing:null,source_page:55,note:`ABSENT`},{id:`ge-12`,movement:`great_entrance`,speaker:`priest`,mode:null,text:`In the tomb with the body, in Hades with the soul, as God; in paradise with the thief, and on the Throne with the Father and the Spirit, wast Thou, O Christ, filling all things, Thyself infinite.`,pointing:null,source_page:55,note:`ABSENT`},{id:`ge-13`,movement:`great_entrance`,speaker:`priest`,mode:null,text:`Thy tomb has shone forth as giving life more splendid than paradise, and more radiant than any royal chamber, O Christ, the fountain of our resurrection!`,pointing:null,source_page:55,note:`ABSENT`},{id:`ge-14`,movement:`great_entrance`,speaker:`rubric`,text:`The priest takes the veils from the holy diskos and chalice and places them on the Holy Table, saying:`,pointing:null,source_page:55,note:`ABSENT`},{id:`ge-15`,movement:`great_entrance`,speaker:`priest`,mode:null,text:`The noble Joseph, when he had taken down Thy Most Pure Body from the tree, wrapped it in fine linen and anointed it with spices, and placed it in a new tomb.`,pointing:null,source_page:55,note:`Same troparion as ge-11, reprinted verbatim as a refrain during veiling — not deduplicated. Page 55 ends here; Great Entrance concludes on later pages, not yet provided.`},{id:`ge-16`,movement:`great_entrance`,speaker:`rubric`,text:`The priest takes the censer from the deacon and censes the Gifts thrice, saying:`,pointing:null,source_page:56,note:`ABSENT`},{id:`ge-17`,movement:`great_entrance`,speaker:`priest`,mode:null,text:`Do good to Zion in Thy good pleasure, and let the walls of Jerusalem be built. Then shalt Thou be pleased with the sacrifice of righteousness, with oblations and whole-burnt offerings; then shall they offer bullocks upon Thine altar!`,pointing:null,source_page:56,note:`ABSENT`},{id:`ge-18`,movement:`great_entrance`,speaker:`rubric`,text:`The priest returns the censer to the deacon; then he bows his head and asks the deacon:`,pointing:null,source_page:56,note:`ABSENT`},{id:`ge-19`,movement:`great_entrance`,speaker:`priest`,mode:null,text:`Remember me, brother and concelebrant.`,pointing:null,source_page:56,note:`ABSENT`},{id:`ge-20`,movement:`great_entrance`,speaker:`deacon`,mode:null,text:`May the Lord God remember your priesthood in His Kingdom.`,pointing:null,source_page:56,note:`ABSENT`},{id:`ge-21`,movement:`great_entrance`,speaker:`priest`,mode:null,text:`Pray for me, my concelebrant.`,pointing:null,source_page:56,note:`ABSENT`},{id:`ge-22`,movement:`great_entrance`,speaker:`deacon`,mode:null,text:`May the Holy Spirit descend on you, and the power of the Most High overshadow you.`,pointing:null,source_page:56,note:`ABSENT`},{id:`ge-23`,movement:`great_entrance`,speaker:`priest`,mode:null,text:`May the Holy Spirit Himself serve together with us all the days of our life.`,pointing:null,source_page:56,note:`ABSENT`},{id:`ge-24`,movement:`great_entrance`,speaker:`deacon`,mode:null,text:`Remember me, holy Master,`,pointing:null,source_page:56,note:`ABSENT`},{id:`ge-25`,movement:`great_entrance`,speaker:`priest`,mode:null,text:`May the Lord God remember you in His Kingdom always, now and ever, and unto ages of ages.`,pointing:null,source_page:56,note:`ABSENT`},{id:`ge-26`,movement:`great_entrance`,speaker:`deacon`,mode:null,text:`Amen.`,pointing:null,source_page:56,note:`ABSENT`},{id:`ge-27`,movement:`great_entrance`,speaker:`rubric`,text:`The deacon kisses the priest's right hand, and then goes to his customary place for the litany.`,pointing:null,source_page:56,note:`ABSENT`},{id:`los-heading`,movement:`litany_of_supplication`,speaker:`heading`,text:`LITANY OF SUPPLICATION`,pointing:null,source_page:56,note:`ABSENT`},{id:`los-01`,movement:`litany_of_supplication`,speaker:`deacon`,mode:null,text:`Let us complete our prayer unto the Lord.`,pointing:null,source_page:56,note:`ABSENT`},{id:`los-02`,movement:`litany_of_supplication`,speaker:`choir`,text:`Lord, have mercy.`,pointing:null,source_page:56,note:`ABSENT`},{id:`los-03`,movement:`litany_of_supplication`,speaker:`deacon`,mode:null,text:`For the Precious Gifts now offered, let us pray to the Lord.`,pointing:null,source_page:57,note:`ABSENT`},{id:`los-04`,movement:`litany_of_supplication`,speaker:`choir`,text:`Lord, have mercy.`,pointing:null,source_page:57,note:`ABSENT`},{id:`los-05`,movement:`litany_of_supplication`,speaker:`deacon`,mode:null,text:`For this holy temple, and for those who enter with faith, reverence, and in the fear of God, let us pray to the Lord.`,pointing:null,source_page:57,note:`ABSENT`},{id:`los-06`,movement:`litany_of_supplication`,speaker:`choir`,text:`Lord, have mercy.`,pointing:null,source_page:57,note:`ABSENT`},{id:`los-07`,movement:`litany_of_supplication`,speaker:`deacon`,mode:null,text:`For our deliverance from all affliction, wrath, danger and necessity, let us pray to the Lord.`,pointing:null,source_page:57,note:`ABSENT`},{id:`los-08`,movement:`litany_of_supplication`,speaker:`choir`,text:`Lord, have mercy.`,pointing:null,source_page:57,note:`ABSENT`},{id:`los-09`,movement:`litany_of_supplication`,speaker:`rubric`,text:`Having placed the Divine Gifts on the Holy Table, the priest quietly prays the Prayer of the Prothesis (Offertory):`,pointing:null,source_page:57,note:`ABSENT`},{id:`los-10`,movement:`litany_of_supplication`,speaker:`priest`,mode:`quiet`,text:`O Lord God Almighty, Who alone art Holy, Who dost accept the sacrifice of praise from those who call upon Thee with their whole heart. Accept also the prayer of us sinners, and bear it to Thy holy altar, enabling us to offer unto Thee gifts and spiritual sacrifices for our sins and for the errors of the people. Make us worthy to find grace in Thy sight, that our sacrifice may be acceptable unto Thee, and that the good Spirit of Thy grace may dwell upon us and upon these Gifts here offered, and upon all Thy people.`,pointing:null,source_page:57,note:`Marked with '*' and '(117)' — replaced in the Liturgy of St. Basil, corresponding prayer on p.117.`},{id:`los-11`,movement:`litany_of_supplication`,speaker:`deacon`,mode:null,text:`Help us, save us, have mercy on us, and keep us, O God, by Thy grace.`,pointing:null,source_page:57,note:`ABSENT`},{id:`los-12`,movement:`litany_of_supplication`,speaker:`choir`,text:`Lord, have mercy.`,pointing:null,source_page:57,note:`ABSENT`},{id:`los-13`,movement:`litany_of_supplication`,speaker:`deacon`,mode:null,text:`That the whole day may be perfect, holy, peaceful, and sinless, let us ask of the Lord.`,pointing:null,source_page:57,note:`Text spans the page break (57→58).`},{id:`los-14`,movement:`litany_of_supplication`,speaker:`choir`,text:`Grant it, O Lord.`,pointing:null,source_page:58,note:`ABSENT`},{id:`los-15`,movement:`litany_of_supplication`,speaker:`deacon`,mode:null,text:`An angel of peace, a faithful guide, a guardian of our souls and bodies, let us ask of the Lord.`,pointing:null,source_page:58,note:`ABSENT`},{id:`los-16`,movement:`litany_of_supplication`,speaker:`choir`,text:`Grant it, O Lord.`,pointing:null,source_page:58,note:`ABSENT`},{id:`los-17`,movement:`litany_of_supplication`,speaker:`deacon`,mode:null,text:`Pardon and remission of our sins and transgressions, let us ask of the Lord.`,pointing:null,source_page:58,note:`ABSENT`},{id:`los-18`,movement:`litany_of_supplication`,speaker:`choir`,text:`Grant it, O Lord.`,pointing:null,source_page:58,note:`ABSENT`},{id:`los-19`,movement:`litany_of_supplication`,speaker:`deacon`,mode:null,text:`All things that are good and profitable for our souls, and peace for the world, let us ask of the Lord.`,pointing:null,source_page:58,note:`ABSENT`},{id:`los-20`,movement:`litany_of_supplication`,speaker:`choir`,text:`Grant it, O Lord.`,pointing:null,source_page:58,note:`ABSENT`},{id:`los-21`,movement:`litany_of_supplication`,speaker:`deacon`,mode:null,text:`That we may complete the remaining time of our life in peace and repentance, let us ask of the Lord.`,pointing:null,source_page:58,note:`ABSENT`},{id:`los-22`,movement:`litany_of_supplication`,speaker:`choir`,text:`Grant it, O Lord.`,pointing:null,source_page:58,note:`ABSENT`},{id:`los-23`,movement:`litany_of_supplication`,speaker:`deacon`,mode:null,text:`A Christian ending to our life, painless, blameless and peaceful; and a good defense before the dread judgment seat of Christ, let us ask of the Lord.`,pointing:null,source_page:58,note:`ABSENT`},{id:`los-24`,movement:`litany_of_supplication`,speaker:`choir`,text:`Grant it, O Lord.`,pointing:null,source_page:58,note:`ABSENT`},{id:`los-25`,movement:`litany_of_supplication`,speaker:`deacon`,mode:null,text:`Commemorating our most holy, most pure, most blessèd and glorious Lady Theotokos and Ever-Virgin Mary with all the saints, let us commend ourselves and each other, and all our life unto Christ our God.`,pointing:null,source_page:58,note:`ABSENT`},{id:`los-26`,movement:`litany_of_supplication`,speaker:`choir`,text:`To Thee, O Lord.`,pointing:null,source_page:58,note:`ABSENT`},{id:`los-27`,movement:`litany_of_supplication`,speaker:`heading`,text:`Exclamation:`,pointing:null,source_page:59,note:`ABSENT`},{id:`los-28`,movement:`litany_of_supplication`,speaker:`priest`,mode:`aloud`,text:`Through the compassions of Thine Only-begotten Son, with Whom Thou art blessed, together with Thine All-Holy, Good, and Life-creating Spirit, now and ever, and unto ages of ages.`,pointing:null,source_page:59,note:`ABSENT`},{id:`los-29`,movement:`litany_of_supplication`,speaker:`choir`,text:`Amen.`,pointing:null,source_page:59,note:`ABSENT`},{id:`kp-01`,movement:`kiss_of_peace`,speaker:`priest`,mode:null,text:`Peace be unto all.`,pointing:null,source_page:59,note:`Movement boundary confirmed under the ratified v5 rule — content-derived; no heading printed.`},{id:`kp-02`,movement:`kiss_of_peace`,speaker:`choir`,text:`And to your spirit.`,pointing:null,source_page:59,note:`ABSENT`},{id:`kp-03`,movement:`kiss_of_peace`,speaker:`deacon`,mode:null,text:`Let us love one another, that with one mind we may confess:`,pointing:null,source_page:59,note:`ABSENT`},{id:`kp-04`,movement:`kiss_of_peace`,speaker:`choir`,text:`Father, Son and Holy Spirit! The Trinity, One in Essence, and Undivided!`,pointing:null,source_page:59,note:`ABSENT`},{id:`kp-05`,movement:`kiss_of_peace`,speaker:`rubric`,text:`The priest bows three times before the Holy Table, saying each time:`,pointing:null,source_page:59,note:`ABSENT`},{id:`kp-06`,movement:`kiss_of_peace`,speaker:`priest`,mode:null,text:`I will love Thee, O Lord, my strength. The Lord is my foundation, my refuge, and my deliverer. {{(3)}}`,pointing:null,source_page:59,note:`ABSENT`},{id:`kp-07`,movement:`kiss_of_peace`,speaker:`rubric`,text:`And he kisses the Holy Things, which remain covered, thus: first the top of the holy diskos, then the top of the holy chalice, and the edge of the Holy Table in front of him. If there are two or more priests, they all kiss the Holy Things and each other on the shoulder. The celebrant says: 'Christ is in our midst.' And the one he kisses answers: 'He is and ever shall be.'`,pointing:null,source_page:59,note:`Embedded dialogue kept inside the rubric quote rather than split into separate speaker units — conditional (multiple concelebrating priests only) and the source gives no clean speaker labels for it beyond 'the celebrant' / 'the one he kisses.'`},{id:`kp-08`,movement:`kiss_of_peace`,speaker:`rubric`,text:`If two or more deacons remain in the sanctuary, they kiss their oraria where the cross is depicted and exchange the Kiss of Peace with each other in like manner to the priests.`,pointing:null,source_page:59,note:`ABSENT`},{id:`kp-09`,movement:`kiss_of_peace`,speaker:`rubric`,text:`The deacon on the amvon, similarly makes reverences standing in his place, kisses his own orarion where the cross is depicted, and then exclaims:`,pointing:null,source_page:59,note:`Text spans the page break (59→60).`},{id:`kp-10`,movement:`kiss_of_peace`,speaker:`deacon`,mode:null,text:`The doors! The doors! In wisdom, let us attend!`,pointing:null,source_page:60,note:`ABSENT`},{id:`cr-heading`,movement:`creed`,speaker:`heading`,text:`CREED`,pointing:null,source_page:60,note:`ABSENT`},{id:`cr-01`,movement:`creed`,speaker:`rubric`,text:`The priest lifts the large aer and raises it up and down over the Holy Gifts. If several priests are serving, then they lift the holy aer and hold it over the Holy Gifts and raise it up and down saying to themselves the Confession of the Faith, as do the people.`,pointing:null,source_page:60,note:`ABSENT`},{id:`cr-02`,movement:`creed`,speaker:`people`,text:`I believe in One God, the Father Almighty, Maker of heaven and earth, and of all things visible and invisible. And in One Lord Jesus Christ, the Son of God, the Only-begotten, begotten of the Father before all ages. Light of Light; true God of true God; Begotten, not made; of One Essence with the Father, by Whom all things were made; Who for us men and for our salvation came down from heaven, and was incarnate of the Holy Spirit and the Virgin Mary, and became man. And He was crucified for us under Pontius Pilate, and suffered, and was buried. And the third day He rose again, according to the Scriptures, and ascended into heaven, and sits at the right hand of the Father; and He shall come again with glory to judge the living and the dead; Whose Kingdom shall have no end. And in the Holy Spirit, the Lord, the Giver of Life, Who proceeds from the Father; Who with the Father and the Son together is worshipped and glorified; Who spoke by the prophets. In One, Holy, Catholic and Apostolic Church. I acknowledge one baptism for the remission of sins. I look for the resurrection of the dead, and the life of the world to come. Amen.`,pointing:null,source_page:60,note:`Speaker printed as 'PEOPLE:', not 'CHOIR:' — first confirmed use of this distinct label in the source.`},{id:`ad-heading`,movement:`anaphora_dialogue`,speaker:`heading`,text:`ANAPHORA`,pointing:null,source_page:61,note:`ABSENT`},{id:`ad-01`,movement:`anaphora_dialogue`,speaker:`deacon`,mode:null,text:`Let us stand aright! Let us stand with fear! Let us attend, that we may offer the Holy Oblation in peace.`,pointing:null,source_page:61,note:`ABSENT`},{id:`ad-02`,movement:`anaphora_dialogue`,speaker:`choir`,text:`A mercy of peace! A sacrifice of praise!`,pointing:null,source_page:61,note:`ABSENT`},{id:`ad-03`,movement:`anaphora_dialogue`,speaker:`rubric`,text:`The priest, having taken the aer off of the Holy Things, kisses it, and lays it to one side, saying: 'The grace of our Lord....' The deacon, having made a reverence, returns into the sanctuary, and taking a fan, devoutly fans the Holy Things [now done only at ordinations].`,pointing:null,source_page:61,note:`ABSENT`},{id:`ad-04`,movement:`anaphora_dialogue`,speaker:`heading`,text:`Exclamation:`,pointing:null,source_page:61,note:`ABSENT`},{id:`ad-05`,movement:`anaphora_dialogue`,speaker:`priest`,mode:`aloud`,text:`The grace of our Lord Jesus Christ, the love of God the Father, and the communion of the Holy Spirit be with all of you.`,pointing:null,source_page:61,note:`ABSENT`},{id:`ad-06`,movement:`anaphora_dialogue`,speaker:`choir`,text:`And with your spirit.`,pointing:null,source_page:61,note:`ABSENT`},{id:`ad-07`,movement:`anaphora_dialogue`,speaker:`priest`,mode:null,cue:`(facing east)`,text:`Let us lift up our hearts.`,pointing:null,source_page:61,note:`Printed inline annotation '(facing east)' — a directional/staging cue, not aloud/quiet or tempo. Doesn't fit mode, so it's carried in its own cue field and rendered verbatim.`},{id:`ad-08`,movement:`anaphora_dialogue`,speaker:`choir`,text:`We lift them up unto the Lord.`,pointing:null,source_page:61,note:`ABSENT`},{id:`ad-09`,movement:`anaphora_dialogue`,speaker:`priest`,mode:null,text:`Let us give thanks unto the Lord.`,pointing:null,source_page:61,note:`ABSENT`},{id:`ad-10`,movement:`anaphora_dialogue`,speaker:`choir`,text:`It is meet and right to worship the Father, and the Son, and the Holy Spirit: the Trinity, One in essence, and undivided.`,pointing:null,source_page:61,note:`ABSENT`},{id:`ap-01`,movement:`anaphora_preface`,speaker:`rubric`,text:`And the priest prays quietly:`,pointing:null,source_page:61,note:`ABSENT`},{id:`ap-02`,movement:`anaphora_preface`,speaker:`priest`,mode:`quiet`,text:`It is meet and right to hymn Thee, to bless Thee, to give thanks to Thee, and to worship Thee in every place of Thy dominion: for Thou art God ineffable, inconceivable, invisible, incomprehensible, ever-existing and eternally the same, Thou and Thine Only-begotten Son and Thy Holy Spirit. Thou it was Who brought us from non-existence into being, and when we had fallen away didst raise us up again, and didst not cease to do all things until thou hadst brought us up to heaven, and hadst endowed us with Thy Kingdom which is to come. For all these things we give thanks to Thee, and to Thine Only-begotten Son, and to Thy Holy Spirit; for all things of which we know and of which we know not, whether manifest or unseen; and we thank Thee for this Liturgy which Thou hast deigned to accept at our hands, though there stand by Thee thousands of archangels and hosts of angels, the Cherubim and the Seraphim, six-winged, many-eyed, who soar aloft, borne on their pinions...`,pointing:null,source_page:61,note:`Source read 'didst raise is up again' — confirmed print typo, corrected to 'us' per Bill's check against the physical book. Marked with '*' and '(118)' — replaced in the Liturgy of St. Basil. Spans the page break (61→62).`},{id:`as-01`,movement:`anaphora_sanctus`,speaker:`heading`,text:`Exclamation:`,pointing:null,source_page:62,note:`ABSENT`},{id:`as-02`,movement:`anaphora_sanctus`,speaker:`priest`,mode:`aloud`,text:`Singing the triumphant hymn, shouting, proclaiming and saying:`,pointing:null,source_page:62,note:`ABSENT`},{id:`as-03`,movement:`anaphora_sanctus`,speaker:`rubric`,text:`As the priest chants the above, the deacon touches the diskos with each of the points of the star (making the Sign of the Cross—east, west, north and south), then kisses it and lays it aside; he goes to the right side of the Holy Table.`,pointing:null,source_page:62,note:`ABSENT`},{id:`as-04`,movement:`anaphora_sanctus`,speaker:`choir`,text:`Holy! Holy! Holy! Lord of Sabbaoth! Heaven and earth are full of Thy glory! Hosanna in the highest! Blessèd is He that comes in the Name of the Lord! Hosanna in the highest!`,pointing:null,source_page:62,note:`ABSENT`},{id:`ai-01`,movement:`anaphora_institution`,speaker:`rubric`,text:`The priest quietly prays:`,pointing:null,source_page:62,note:`ABSENT`},{id:`ai-02`,movement:`anaphora_institution`,speaker:`priest`,mode:`quiet`,text:`With these blessèd powers, O Master Who lovest mankind, we also cry aloud and say: Holy art Thou and All-Holy, Thou and Thine Only-begotten Son and Thy Holy Spirit! Holy art Thou and All-Holy, and magnificent is Thy glory! Who hast so loved Thy world as to give Thine Only-begotten Son, that whoever believes in Him should not perish but have everlasting life; Who when He had come and had fulfilled all the dispensation for us, in the night in which He was given up — or rather, gave Himself up for the life of the world — took bread in His holy, pure, and blameless hands; and when He had given thanks and blessed it, and hallowed it, and broken it, He gave it to His holy disciples and apostles saying:`,pointing:null,source_page:62,note:`Marked with '*' and '(120)'. Spans the page break (62→63).`},{id:`ai-03`,movement:`anaphora_institution`,speaker:`heading`,text:`Exclamation:`,pointing:null,source_page:63,note:`ABSENT`},{id:`ai-04`,movement:`anaphora_institution`,speaker:`priest`,mode:`aloud`,text:`Take! Eat! This is My Body which is broken for you, for the remission of sins.`,pointing:null,source_page:63,note:`Source does not reprint a 'PRIEST:' label before this line (unlike other Exclamations) — speaker inferred from context and typesetting, not an explicit printed label.`},{id:`ai-05`,movement:`anaphora_institution`,speaker:`choir`,text:`Amen.`,pointing:null,source_page:63,note:`ABSENT`},{id:`ai-06`,movement:`anaphora_institution`,speaker:`rubric`,text:`As this is being said, the deacon points to the holy diskos, holding his orarion with three fingers of his right hand, and in like manner when the priest says 'Drink of it, all of you...,' he points to the holy chalice.`,pointing:null,source_page:63,note:`ABSENT`},{id:`ai-07`,movement:`anaphora_institution`,speaker:`priest`,mode:`quiet`,cue:`(quietly)`,text:`And likewise, after supper, He took the cup, saying:`,pointing:null,source_page:63,note:`Explicitly marked '(quietly)' inline — rendered verbatim as the cue.`},{id:`ai-08`,movement:`anaphora_institution`,speaker:`heading`,text:`Exclamation:`,pointing:null,source_page:63,note:`ABSENT`},{id:`ai-09`,movement:`anaphora_institution`,speaker:`priest`,mode:`aloud`,text:`Drink of it, all of you! This is My Blood of the New Testament, which is shed for you and for many, for the remission of sins!`,pointing:null,source_page:63,note:`Marked with '*' and '(122)'.`},{id:`ai-10`,movement:`anaphora_institution`,speaker:`choir`,text:`Amen.`,pointing:null,source_page:63,note:`ABSENT`},{id:`aa-01`,movement:`anaphora_anamnesis`,speaker:`rubric`,text:`The priest quietly prays:`,pointing:null,source_page:64,note:`ABSENT`},{id:`aa-02`,movement:`anaphora_anamnesis`,speaker:`priest`,mode:`quiet`,text:`Remembering this saving commandment and all those things which have come to pass for us: the Cross, the Tomb, the Resurrection on the third day, the Ascension into heaven, the Sitting at the right hand, and the second and glorious Coming.`,pointing:null,source_page:64,note:`Marked with '*' and '(123)'.`},{id:`aa-03`,movement:`anaphora_anamnesis`,speaker:`rubric`,text:`And the deacon crosses his right hand over his left and elevates the holy diskos and the holy chalice with devout reverence, as the priest exclaims:`,pointing:null,source_page:64,note:`ABSENT`},{id:`aa-04`,movement:`anaphora_anamnesis`,speaker:`priest`,mode:`aloud`,text:`Thine own of Thine own, we offer unto Thee, in behalf of all and for all.`,pointing:null,source_page:64,note:`No 'Exclamation:' heading printed this time — mode:aloud inferred from the rubric's own word 'exclaims' plus upright typesetting.`},{id:`aa-05`,movement:`anaphora_anamnesis`,speaker:`choir`,cue:`(slowly)`,text:`We praise Thee, we bless Thee, we give thanks unto Thee, O Lord; and we pray unto Thee, O our God.`,pointing:null,source_page:64,note:`Printed inline annotation '(slowly)' — tempo direction, carried in its own cue field and rendered verbatim.`},{id:`ae-01`,movement:`anaphora_epiclesis`,speaker:`rubric`,text:`As the priest quietly prays:`,pointing:null,source_page:64,note:`ABSENT`},{id:`ae-02`,movement:`anaphora_epiclesis`,speaker:`priest`,mode:`quiet`,text:`Again we offer unto Thee this rational and bloodless worship, and ask Thee, and pray Thee, and supplicate Thee: Send down Thy Holy Spirit upon us and upon these Gifts here offered.`,pointing:null,source_page:64,note:`Marked with '*' and '(123)'.`},{id:`ae-03`,movement:`anaphora_epiclesis`,speaker:`rubric`,text:`The priest and the deacon bow three times before the Holy Table as they say:`,pointing:null,source_page:64,note:`ABSENT`},{id:`ae-04`,movement:`anaphora_epiclesis`,speaker:`priest`,mode:null,text:`O Lord, Who didst send down Thy Most Holy Spirit upon Thine apostles at the third hour: Take Him not from us, O Good One, but renew Him in us who pray to Thee.`,pointing:null,source_page:64,note:`First of three recitations of this verse, per ae-03's rubric.`},{id:`ae-05`,movement:`anaphora_epiclesis`,speaker:`deacon`,mode:null,text:`Create in me a clean heart, O God, and renew a right spirit within me.`,pointing:null,source_page:64,note:`ABSENT`},{id:`ae-06`,movement:`anaphora_epiclesis`,speaker:`priest`,mode:null,text:`O Lord, Who didst send down Thy Most Holy Spirit upon Thine apostles at the third hour: Take Him not from us, O Good One, but renew Him in us who pray to Thee.`,pointing:null,source_page:64,note:`Second recitation; text spans the page break (64→65).`},{id:`ae-07`,movement:`anaphora_epiclesis`,speaker:`deacon`,mode:null,text:`Cast me not away from Thy presence, and take not Thy Holy Spirit from me.`,pointing:null,source_page:65,note:`ABSENT`},{id:`ae-08`,movement:`anaphora_epiclesis`,speaker:`priest`,mode:null,text:`O Lord, Who didst send down Thy Most Holy Spirit upon Thine apostles at the third hour: Take Him not from us, O Good One, but renew Him in us who pray to Thee.`,pointing:null,source_page:65,note:`Third and final recitation, per ae-03's rubric.`},{id:`ae-09`,movement:`anaphora_epiclesis`,speaker:`rubric`,text:`Then bowing his head and pointing to the diskos and the Holy Bread with his orarion, the deacon says:`,pointing:null,source_page:65,note:`ABSENT`},{id:`ae-10`,movement:`anaphora_epiclesis`,speaker:`deacon`,mode:null,text:`Bless, Master, the Holy Bread.`,pointing:null,source_page:65,note:`ABSENT`},{id:`ae-11`,movement:`anaphora_epiclesis`,speaker:`rubric`,text:`The priest blesses the Holy Bread with the Sign of the Cross, saying:`,pointing:null,source_page:65,note:`ABSENT`},{id:`ae-12`,movement:`anaphora_epiclesis`,speaker:`priest`,mode:null,text:`And make this Bread the Precious Body of Thy Christ.`,pointing:null,source_page:65,note:`ABSENT`},{id:`ae-13`,movement:`anaphora_epiclesis`,speaker:`deacon`,mode:null,text:`Amen.`,pointing:null,source_page:65,note:`ABSENT`},{id:`ae-14`,movement:`anaphora_epiclesis`,speaker:`rubric`,text:`The deacon points to the chalice, saying:`,pointing:null,source_page:65,note:`ABSENT`},{id:`ae-15`,movement:`anaphora_epiclesis`,speaker:`deacon`,mode:null,text:`Bless, Master, the Holy Cup.`,pointing:null,source_page:65,note:`ABSENT`},{id:`ae-16`,movement:`anaphora_epiclesis`,speaker:`rubric`,text:`The priest blesses the Holy Cup with the Sign of the Cross, saying:`,pointing:null,source_page:65,note:`ABSENT`},{id:`ae-17`,movement:`anaphora_epiclesis`,speaker:`priest`,mode:null,text:`And that which is in this Cup, the Precious Blood of Thy Christ.`,pointing:null,source_page:65,note:`ABSENT`},{id:`ae-18`,movement:`anaphora_epiclesis`,speaker:`deacon`,mode:null,text:`Amen.`,pointing:null,source_page:65,note:`ABSENT`},{id:`ae-19`,movement:`anaphora_epiclesis`,speaker:`rubric`,text:`The deacon points to both, saying:`,pointing:null,source_page:65,note:`ABSENT`},{id:`ae-20`,movement:`anaphora_epiclesis`,speaker:`deacon`,mode:null,text:`Bless both, Master.`,pointing:null,source_page:65,note:`ABSENT`},{id:`ae-21`,movement:`anaphora_epiclesis`,speaker:`rubric`,text:`The priest blesses the Holy Gifts, saying:`,pointing:null,source_page:66,note:`ABSENT`},{id:`ae-22`,movement:`anaphora_epiclesis`,speaker:`priest`,mode:`aloud`,text:`Making the change by Thy Holy Spirit.`,pointing:null,source_page:66,note:`ABSENT`},{id:`ae-23`,movement:`anaphora_epiclesis`,speaker:`deacon`,mode:null,text:`Amen. Amen. Amen.`,pointing:null,source_page:66,note:`ABSENT`},{id:`ae-24`,movement:`anaphora_epiclesis`,speaker:`rubric`,text:`The deacon bows his head to the priest and says:`,pointing:null,source_page:66,note:`ABSENT`},{id:`ae-25`,movement:`anaphora_epiclesis`,speaker:`deacon`,mode:null,text:`Remember me, a sinner, holy Master.`,pointing:null,source_page:66,note:`ABSENT`},{id:`ae-26`,movement:`anaphora_epiclesis`,speaker:`priest`,mode:null,text:`May the Lord God remember you in His Kingdom always, now and ever, and unto ages of ages.`,pointing:null,source_page:66,note:`ABSENT`},{id:`ae-27`,movement:`anaphora_epiclesis`,speaker:`deacon`,mode:null,text:`Amen.`,pointing:null,source_page:66,note:`ABSENT`},{id:`cm-01`,movement:`commemorations`,speaker:`rubric`,text:`The priest makes a low bow before the Holy Table and continues to pray quietly:`,pointing:null,source_page:66,note:`Movement boundary confirmed under the ratified v5 rule — content-derived; no heading printed.`},{id:`cm-02`,movement:`commemorations`,speaker:`priest`,mode:`quiet`,text:`That they may be to those who partake for the purification of soul, for the remission of sins, for the communion of Thy Holy Spirit, for the fulfillment of the Kingdom of Heaven, for boldness towards Thee, and not for judgment or condemnation.`,pointing:null,source_page:66,note:`Marked with '*' and '(125)'.`},{id:`cm-03`,movement:`commemorations`,speaker:`priest`,mode:`quiet`,text:`Again we offer unto Thee this rational worship for those who have fallen asleep in the faith: ancestors, fathers, patriarchs, prophets, apostles, preachers, evangelists, martyrs, confessors, ascetics, and for every righteous spirit made perfect in faith.`,pointing:null,source_page:66,note:`ABSENT`},{id:`cm-04`,movement:`commemorations`,speaker:`rubric`,text:`The priest censes the Holy Table thrice, while making the exclamation:`,pointing:null,source_page:66,note:`ABSENT`},{id:`cm-05`,movement:`commemorations`,speaker:`priest`,mode:`aloud`,text:`Especially for our most holy, most pure, most blessèd and glorious Lady Theotokos and Ever-Virgin Mary.`,pointing:null,source_page:66,note:`ABSENT`},{id:`cm-06`,movement:`commemorations`,speaker:`rubric`,text:`Then hands the censer to the deacon who continues to cense the Holy Table and the sanctuary.`,pointing:null,source_page:66,note:`ABSENT`},{id:`cm-heading`,movement:`commemorations`,speaker:`heading`,text:`HYMN TO THE THEOTOKOS *`,pointing:null,source_page:67,note:`Asterisk ties to cm-footnote.`},{id:`cm-07`,movement:`commemorations`,speaker:`choir`,text:`It is truly meet to bless you, O Theotokos, ever-blessèd and most pure, and the Mother of our God. More honorable than the Cherubim, and more glorious beyond compare than the Seraphim: without defilement you gave birth to God the Word: true Theotokos, we magnify you.`,pointing:null,source_page:67,note:`ABSENT`},{id:`cm-08`,movement:`commemorations`,speaker:`rubric`,text:`During the singing of this hymn, the priest continues to pray:`,pointing:null,source_page:67,note:`ABSENT`},{id:`cm-09`,movement:`commemorations`,speaker:`priest`,mode:`quiet`,text:`For the holy Prophet, Forerunner, and Baptist John; the holy glorious, and all-laudable apostles; Saint ___ {{(of the day)}} whom we commemorate today; and all Thy saints, at whose supplication look down upon us, O God. Remember all those who have fallen asleep before us in the hope of resurrection to eternal life, especially ___; grant them rest, O God, where the light of Thy countenance shines on them.`,pointing:null,source_page:67,note:`Marked with '*' and '(126)'.`},{id:`cm-10`,movement:`commemorations`,speaker:`priest`,mode:`quiet`,text:`Again we entreat Thee: Remember, O Lord, all the Orthodox Episcopate, who rightly teach the word of Thy truth; all the priests, the deacons in Christ, and every order of the clergy.`,pointing:null,source_page:67,note:`ABSENT`},{id:`cm-11`,movement:`commemorations`,speaker:`priest`,mode:`quiet`,text:`Again we offer unto Thee this rational worship: for the Holy Catholic, and Apostolic Church; for those who live in chastity and holiness of life; for all civil authorities; grant them, O Lord, peaceful times, that we, in their tranquility, may lead a calm and peaceful life in all godliness and sanctity.`,pointing:null,source_page:67,note:`ABSENT`},{id:`cm-footnote`,movement:`commemorations`,speaker:`rubric`,text:`On certain Feast Days, this is replaced by the 9th Ode of the Canon. See Appendix VI — VII.`,pointing:null,source_page:67,note:`ABSENT`},{id:`cm-12`,movement:`commemorations`,speaker:`rubric`,text:`And after the choir concludes the hymn, the priest exclaims:`,pointing:null,source_page:68,note:`ABSENT`},{id:`cm-13`,movement:`commemorations`,speaker:`priest`,mode:`aloud`,text:`Among the first, remember, O Lord, His Beatitude, our lord, the Most blessèd ___, Archbishop of {{[city]}}, Metropolitan of All America and Canada, and His Eminence (His Grace), our lord, the Most reverend (Right reverend) ___, Archbishop (Bishop) of {{[city]}}. Grant them for Thy Holy Churches in peace, safety, honor, health, and length of days, rightly to divide the word of Thy truth.`,pointing:null,source_page:68,note:`'[city]' is a square-bracket red instructional placeholder — same {{...}} treatment as the round-bracket editorial alternatives, since it's still a single red span inline in an otherwise black sentence. (The earlier '[General]' bracket on p.42 was originally left unwrapped; fixed retroactively per spec v9.) This edition's diptychs name the Antiochian Archdiocese primate specifically ('Metropolitan of All America and Canada'). Basil: SHARED, not overridden. Compared word by word against Appendix IV p.128 (spec v20 step 4): identical, 381 characters each, including the blank and [city] placeholders. Basil differs around this Exclamation (the quiet prayers before and after are reordered; see cm-10, b-cm-11b, cm-16), but the Exclamation itself is the same in both Liturgies.`},{id:`cm-14`,movement:`commemorations`,speaker:`choir`,text:`And all mankind.`,pointing:null,source_page:68,note:`ABSENT`},{id:`cm-15`,movement:`commemorations`,speaker:`rubric`,text:`And the priest continues to pray quietly:`,pointing:null,source_page:68,note:`ABSENT`},{id:`cm-16`,movement:`commemorations`,speaker:`priest`,mode:`quiet`,text:`Remember, O Lord, the city {{(or village, or holy habitation)}}, in which we dwell, every city and country; those who in faith dwell in them. Remember, O Lord, travelers by land, by sea, and by air; the sick and the suffering; captives, and their salvation. Remember, O Lord, those who bring offerings and do good works in Thy Holy Churches; those who remember the poor; and upon us all send forth Thy mercies.`,pointing:null,source_page:68,note:`Marked with '*' and '(128)'.`},{id:`cm-17`,movement:`commemorations`,speaker:`rubric`,text:`(And here he remembers by name the living faithful, whom he will).`,pointing:null,source_page:68,note:`ABSENT`},{id:`cm-18`,movement:`commemorations`,speaker:`heading`,text:`Exclamation:`,pointing:null,source_page:68,note:`ABSENT`},{id:`cm-19`,movement:`commemorations`,speaker:`priest`,mode:`aloud`,text:`And grant that with one mouth and one heart we may praise Thine all-honorable and majestic Name: of the Father, and of the Son, and of the Holy Spirit, now and ever, and unto ages of ages.`,pointing:null,source_page:68,note:`ABSENT`},{id:`cm-20`,movement:`commemorations`,speaker:`choir`,text:`Amen.`,pointing:null,source_page:68,note:`ABSENT`},{id:`lblp-01`,movement:`litany_before_lords_prayer`,speaker:`rubric`,text:`The priest turns and blesses the people:`,pointing:null,source_page:69,note:`ABSENT`},{id:`lblp-02`,movement:`litany_before_lords_prayer`,speaker:`priest`,mode:null,text:`And may the mercies of our great God and Savior Jesus Christ be with all of you.`,pointing:null,source_page:69,note:`ABSENT`},{id:`lblp-03`,movement:`litany_before_lords_prayer`,speaker:`choir`,text:`And with your spirit.`,pointing:null,source_page:69,note:`ABSENT`},{id:`lblp-04`,movement:`litany_before_lords_prayer`,speaker:`rubric`,text:`The deacon, having received leave from the priest comes out through the north door, and standing in his customary place begins:`,pointing:null,source_page:69,note:`ABSENT`},{id:`lblp-heading`,movement:`litany_before_lords_prayer`,speaker:`heading`,text:`LITANY BEFORE THE LORD'S PRAYER`,pointing:null,source_page:69,note:`ABSENT`},{id:`lblp-05`,movement:`litany_before_lords_prayer`,speaker:`deacon`,mode:null,text:`Having remembered all the saints, again and again in peace let us pray to the Lord.`,pointing:null,source_page:69,note:`ABSENT`},{id:`lblp-06`,movement:`litany_before_lords_prayer`,speaker:`choir`,text:`Lord, have mercy.`,pointing:null,source_page:69,note:`ABSENT`},{id:`lblp-07`,movement:`litany_before_lords_prayer`,speaker:`deacon`,mode:null,text:`For the Precious Gifts offered and sanctified, let us pray to the Lord.`,pointing:null,source_page:69,note:`ABSENT`},{id:`lblp-08`,movement:`litany_before_lords_prayer`,speaker:`choir`,text:`Lord, have mercy.`,pointing:null,source_page:69,note:`ABSENT`},{id:`lblp-09`,movement:`litany_before_lords_prayer`,speaker:`deacon`,mode:null,text:`That our God, Who lovest mankind, receiving them upon His holy, heavenly, and ideal altar as a sweet spiritual fragrance, will send down upon us in return His divine grace and the gift of the Holy Spirit, let us pray to the Lord.`,pointing:null,source_page:69,note:`ABSENT`},{id:`lblp-10`,movement:`litany_before_lords_prayer`,speaker:`choir`,text:`Lord, have mercy.`,pointing:null,source_page:69,note:`ABSENT`},{id:`lblp-11`,movement:`litany_before_lords_prayer`,speaker:`deacon`,mode:null,text:`For our deliverance from all affliction, wrath, danger and necessity, let us pray to the Lord.`,pointing:null,source_page:69,note:`ABSENT`},{id:`lblp-12`,movement:`litany_before_lords_prayer`,speaker:`choir`,text:`Lord, have mercy.`,pointing:null,source_page:69,note:`ABSENT`},{id:`lblp-13`,movement:`litany_before_lords_prayer`,speaker:`rubric`,text:`And the priest quietly prays:`,pointing:null,source_page:69,note:`ABSENT`},{id:`lblp-14`,movement:`litany_before_lords_prayer`,speaker:`priest`,mode:`quiet`,text:`Unto Thee we commend our whole life and our hope, O Master Who lovest mankind. We ask Thee, and pray Thee, and supplicate Thee: Make us worthy to partake of the Heavenly and Awesome Mysteries of this sacred and spiritual table with a pure conscience: for remission of sins, for forgiveness of transgressions, for the communion of the Holy Spirit, for the inheritance of the Kingdom of Heaven, for boldness towards Thee, but not for judgment or condemnation.`,pointing:null,source_page:69,note:`Marked with '*' and '(129)'. Spans the page break (69→70).`},{id:`lblp-15`,movement:`litany_before_lords_prayer`,speaker:`deacon`,mode:null,text:`Help us, save us, have mercy on us, and keep us, O God, by Thy grace.`,pointing:null,source_page:70,note:`ABSENT`},{id:`lblp-16`,movement:`litany_before_lords_prayer`,speaker:`choir`,text:`Lord, have mercy.`,pointing:null,source_page:70,note:`ABSENT`},{id:`lblp-17`,movement:`litany_before_lords_prayer`,speaker:`deacon`,mode:null,text:`That the whole day may be perfect, holy, peaceful and sinless, let us ask of the Lord.`,pointing:null,source_page:70,note:`ABSENT`},{id:`lblp-18`,movement:`litany_before_lords_prayer`,speaker:`choir`,text:`Grant it, O Lord.`,pointing:null,source_page:70,note:`ABSENT`},{id:`lblp-19`,movement:`litany_before_lords_prayer`,speaker:`deacon`,mode:null,text:`An angel of peace, a faithful guide, a guardian of our souls and bodies, let us ask of the Lord.`,pointing:null,source_page:70,note:`ABSENT`},{id:`lblp-20`,movement:`litany_before_lords_prayer`,speaker:`choir`,text:`Grant it, O Lord.`,pointing:null,source_page:70,note:`ABSENT`},{id:`lblp-21`,movement:`litany_before_lords_prayer`,speaker:`deacon`,mode:null,text:`Pardon and remission of our sins and transgressions, let us ask of the Lord.`,pointing:null,source_page:70,note:`ABSENT`},{id:`lblp-22`,movement:`litany_before_lords_prayer`,speaker:`choir`,text:`Grant it, O Lord.`,pointing:null,source_page:70,note:`ABSENT`},{id:`lblp-23`,movement:`litany_before_lords_prayer`,speaker:`deacon`,mode:null,text:`All things that are good and profitable for our souls, and peace for the world, let us ask of the Lord.`,pointing:null,source_page:70,note:`ABSENT`},{id:`lblp-24`,movement:`litany_before_lords_prayer`,speaker:`choir`,text:`Grant it, O Lord.`,pointing:null,source_page:70,note:`ABSENT`},{id:`lblp-25`,movement:`litany_before_lords_prayer`,speaker:`deacon`,mode:null,text:`That we may complete the remaining time of our life in peace and repentance, let us ask of the Lord.`,pointing:null,source_page:70,note:`ABSENT`},{id:`lblp-26`,movement:`litany_before_lords_prayer`,speaker:`choir`,text:`Grant it, O Lord.`,pointing:null,source_page:70,note:`ABSENT`},{id:`lblp-27`,movement:`litany_before_lords_prayer`,speaker:`deacon`,mode:null,text:`A Christian ending to our life: painless, blameless, and peaceful; and a good defense before the dread judgment seat of Christ, let us ask of the Lord.`,pointing:null,source_page:70,note:`Text spans the page break (70→71).`},{id:`lblp-28`,movement:`litany_before_lords_prayer`,speaker:`choir`,text:`Grant it, O Lord.`,pointing:null,source_page:71,note:`ABSENT`},{id:`lblp-29`,movement:`litany_before_lords_prayer`,speaker:`deacon`,mode:null,text:`Having asked for the unity of the Faith and the communion of the Holy Spirit, let us commend ourselves and each other, and all our life unto Christ our God.`,pointing:null,source_page:71,note:`ABSENT`},{id:`lblp-30`,movement:`litany_before_lords_prayer`,speaker:`choir`,text:`To Thee, O Lord.`,pointing:null,source_page:71,note:`ABSENT`},{id:`lblp-31`,movement:`litany_before_lords_prayer`,speaker:`heading`,text:`Exclamation:`,pointing:null,source_page:71,note:`ABSENT`},{id:`lblp-32`,movement:`litany_before_lords_prayer`,speaker:`priest`,mode:`aloud`,text:`And make us worthy, O Master, that with boldness and without condemnation we may dare to call upon Thee, the heavenly God, as Father, and to say:`,pointing:null,source_page:71,note:`ABSENT`},{id:`lp-01`,movement:`lords_prayer`,speaker:`people`,text:`Our Father, Who art in heaven, hallowed be Thy Name. Thy Kingdom come. Thy Will be done, on earth as it is in heaven. Give us this day our daily bread; and forgive us our trespasses, as we forgive those who trespass against us; and lead us not into temptation, but deliver us from the evil one.`,pointing:null,source_page:71,note:`Movement boundary confirmed under the ratified v5 rule — content-derived; no heading printed.`},{id:`lp-02`,movement:`lords_prayer`,speaker:`rubric`,text:`While the Lord's Prayer is being sung, the deacon, standing before the Royal Doors, crosses his orarion over his shoulders.`,pointing:null,source_page:71,note:`ABSENT`},{id:`lp-03`,movement:`lords_prayer`,speaker:`heading`,text:`Exclamation:`,pointing:null,source_page:71,note:`ABSENT`},{id:`lp-04`,movement:`lords_prayer`,speaker:`priest`,mode:`aloud`,text:`For Thine is the kingdom, and the power, and the glory; of the Father, and of the Son, and of the Holy Spirit, now and ever, and unto ages of ages.`,pointing:null,source_page:71,note:`ABSENT`},{id:`lp-05`,movement:`lords_prayer`,speaker:`choir`,text:`Amen.`,pointing:null,source_page:71,note:`ABSENT`},{id:`boh-01`,movement:`bowing_of_heads`,speaker:`priest`,mode:null,text:`Peace be unto all.`,pointing:null,source_page:71,note:`Movement boundary confirmed under the ratified v5 rule — content-derived; no heading printed.`},{id:`boh-02`,movement:`bowing_of_heads`,speaker:`choir`,text:`And to your spirit.`,pointing:null,source_page:71,note:`ABSENT`},{id:`boh-03`,movement:`bowing_of_heads`,speaker:`deacon`,mode:null,text:`Bow your heads unto the Lord.`,pointing:null,source_page:71,note:`Text spans the page break (71→72).`},{id:`boh-04`,movement:`bowing_of_heads`,speaker:`choir`,cue:`(slowly)`,text:`To Thee, O Lord.`,pointing:null,source_page:72,note:`Printed inline annotation '(slowly)' — tempo direction, carried in its own cue field and rendered verbatim.`},{id:`boh-05`,movement:`bowing_of_heads`,speaker:`rubric`,text:`While the priest prays quietly:`,pointing:null,source_page:72,note:`ABSENT`},{id:`boh-06`,movement:`bowing_of_heads`,speaker:`priest`,mode:`quiet`,text:`We give thanks unto Thee, O King invisible, Who by Thy measureless power didst make all things, and in the greatness of Thy mercy didst bring all things from non-existence into being. Look down from heaven, O Master, upon those who have bowed their heads unto Thee, for they have not bowed down unto flesh and blood, but unto Thee, the awesome God. Do Thou Thyself, O Master, distribute these gifts here offered, unto all of us for good, according to the individual need of each; sail with those who sail, travel with those who travel by land, by sea and by air; heal the sick, O Thou Who art the physician of our souls and bodies.`,pointing:null,source_page:72,note:`Marked with '*' and '(130)'.`},{id:`boh-07`,movement:`bowing_of_heads`,speaker:`heading`,text:`Exclamation:`,pointing:null,source_page:72,note:`ABSENT`},{id:`boh-08`,movement:`bowing_of_heads`,speaker:`priest`,mode:`aloud`,text:`Through the grace and compassion and Love toward mankind of Thine Only-begotten Son with Whom Thou art blessed, together with Thine All-Holy, Good, and Life-creating Spirit, now and ever, and unto ages of ages.`,pointing:null,source_page:72,note:`ABSENT`},{id:`boh-09`,movement:`bowing_of_heads`,speaker:`choir`,text:`Amen.`,pointing:null,source_page:72,note:`ABSENT`},{id:`ef-01`,movement:`elevation_and_fraction`,speaker:`rubric`,text:`And the priest prays quietly:`,pointing:null,source_page:72,note:`Movement boundary confirmed under the ratified v5 rule — content-derived; no heading printed.`},{id:`ef-02`,movement:`elevation_and_fraction`,speaker:`priest`,mode:`quiet`,text:`Attend, O Lord Jesus Christ our God, out of Thy holy dwelling-place, from the throne of glory of Thy Kingdom; and come to sanctify us, O Thou Who sittest on high with the Father, and art here invisibly present with us; and by Thy mighty hand impart unto us Thy Most Pure Body and Precious Blood, and through us to all the people.`,pointing:null,source_page:72,note:`ABSENT`},{id:`ef-03`,movement:`elevation_and_fraction`,speaker:`rubric`,text:`Now the priest, and likewise the deacon standing at his place, make three low bows, saying silently each time: 'O God, cleanse me a sinner, and have mercy on me...'`,pointing:null,source_page:72,note:`Embedded quoted prayer kept inside the rubric, same handling as the earlier 'Christ is in our midst' exchange. Spans the page break (72→73).`},{id:`ef-04`,movement:`elevation_and_fraction`,speaker:`rubric`,text:`When the deacon sees the priest stretch out his hands and touch the Holy Bread in order to make the elevation, he exclaims:`,pointing:null,source_page:73,note:`ABSENT`},{id:`ef-05`,movement:`elevation_and_fraction`,speaker:`deacon`,mode:null,text:`Let us attend!`,pointing:null,source_page:73,note:`ABSENT`},{id:`ef-06`,movement:`elevation_and_fraction`,speaker:`rubric`,text:`And the priest, taking up the Holy Bread in both hands, elevates it above the Holy Table and exclaims:`,pointing:null,source_page:73,note:`ABSENT`},{id:`ef-07`,movement:`elevation_and_fraction`,speaker:`priest`,mode:`aloud`,text:`The Holy Things for the Holy!`,pointing:null,source_page:73,note:`ABSENT`},{id:`ef-08`,movement:`elevation_and_fraction`,speaker:`choir`,text:`One is Holy! One is the Lord Jesus Christ, to the glory of God the Father! Amen.`,pointing:null,source_page:73,note:`ABSENT`},{id:`ef-heading`,movement:`elevation_and_fraction`,speaker:`heading`,text:`COMMUNION HYMN *`,pointing:null,source_page:73,note:`Asterisk ties to ef-footnote.`},{id:`ef-09`,movement:`elevation_and_fraction`,speaker:`choir`,text:`Praise the Lord from the heavens! Praise Him in the highest! Alleluia! Alleluia! Alleluia!`,pointing:null,source_page:73,note:`ABSENT`},{id:`ef-10`,movement:`elevation_and_fraction`,speaker:`rubric`,text:`After the priest completes the exclamation, he closes the Royal Doors and the curtain is drawn. The deacon then returns to the sanctuary through the south door, stands on the right side of the priest, and at the conclusion of the Communion Hymn says:`,pointing:null,source_page:73,note:`ABSENT`},{id:`ef-heading2`,movement:`elevation_and_fraction`,speaker:`heading`,text:`COMMUNION`,pointing:null,source_page:73,note:`Introduces the fraction/arrangement of the Lamb, not yet the clergy's actual communing — see communion_of_clergy for that boundary.`},{id:`ef-11`,movement:`elevation_and_fraction`,speaker:`deacon`,mode:null,text:`Divide, Master, the Holy Bread.`,pointing:null,source_page:73,note:`ABSENT`},{id:`ef-12`,movement:`elevation_and_fraction`,speaker:`rubric`,text:`The priest divides the Holy Bread into four parts, with due reverence.`,pointing:null,source_page:73,note:`ABSENT`},{id:`ef-13`,movement:`elevation_and_fraction`,speaker:`priest`,mode:null,text:`Divided and distributed is the Lamb of God: Who is divided, yet not disunited; Who is ever eaten, yet never consumed; but sanctifies those who partake thereof.`,pointing:null,source_page:73,note:`ABSENT`},{id:`ef-footnote`,movement:`elevation_and_fraction`,speaker:`rubric`,text:`The text printed here is sung on Sundays only; other days and/or feasts have special hymns. See Appendices VI—VIII.`,pointing:null,source_page:73,note:`ABSENT`},{id:`ef-14`,movement:`elevation_and_fraction`,speaker:`rubric`,text:`Let it be known to you, O priest, that as you divide the Holy Lamb, it is to be placed on the holy diskos with the seal downward, the cut side upward as before, when it was sacrificed.`,pointing:null,source_page:74,note:`ABSENT`},{id:`ef-15`,movement:`elevation_and_fraction`,speaker:`rubric`,text:`Then, you are to place the portion IC toward the upper part of the holy diskos, that is to the east; the portion XC, toward the lower part, that is to the west; and the NI to the north side, and KA to the south side, as shown here:`,pointing:null,source_page:74,note:`ABSENT`},{id:`ef-16`,movement:`elevation_and_fraction`,speaker:`rubric`,text:`[Diagram: a cross-shaped arrangement of four labeled boxes — IC (top/east), NI (left/north), KA (right/south), XC (bottom/west) — showing where each portion of the broken Lamb is placed on the diskos.]`,pointing:null,source_page:74,note:`This is a graphic in the source (a circle with four labeled boxes in a cross layout), not linear text — described here rather than transcribed.`},{id:`ef-17`,movement:`elevation_and_fraction`,speaker:`rubric`,text:`The portion IC is then placed in the chalice. The portion XC is further divided for the communion of the priests and the deacons. The other two portions, NI and KA are for the communion of the faithful people.`,pointing:null,source_page:74,note:`ABSENT`},{id:`ef-18`,movement:`elevation_and_fraction`,speaker:`rubric`,text:`The deacon, then, pointing to the holy chalice, says:`,pointing:null,source_page:74,note:`ABSENT`},{id:`ef-19`,movement:`elevation_and_fraction`,speaker:`deacon`,mode:null,text:`Fill, Master, the Holy Cup.`,pointing:null,source_page:74,note:`ABSENT`},{id:`ef-20`,movement:`elevation_and_fraction`,speaker:`rubric`,text:`As the priest places the portion IC into the chalice, the priest makes the Sign of the Cross with it over the chalice, saying:`,pointing:null,source_page:74,note:`ABSENT`},{id:`ef-21`,movement:`elevation_and_fraction`,speaker:`priest`,mode:null,text:`The fullness of the Holy Spirit.`,pointing:null,source_page:74,note:`ABSENT`},{id:`ef-22`,movement:`elevation_and_fraction`,speaker:`deacon`,mode:null,text:`Amen.`,pointing:null,source_page:74,note:`ABSENT`},{id:`ef-23`,movement:`elevation_and_fraction`,speaker:`rubric`,text:`And taking the hot water, the deacon says to the priest:`,pointing:null,source_page:74,note:`Text spans the page break (74→75).`},{id:`ef-24`,movement:`elevation_and_fraction`,speaker:`deacon`,mode:null,text:`Bless, Master, the warmth.`,pointing:null,source_page:75,note:`ABSENT`},{id:`ef-25`,movement:`elevation_and_fraction`,speaker:`rubric`,text:`The priest blesses the hot water, saying:`,pointing:null,source_page:75,note:`ABSENT`},{id:`ef-26`,movement:`elevation_and_fraction`,speaker:`priest`,mode:null,text:`Blessèd is the warmth of Thy Holy Things always, now and ever, and unto ages of ages. Amen.`,pointing:null,source_page:75,note:`ABSENT`},{id:`ef-27`,movement:`elevation_and_fraction`,speaker:`rubric`,text:`The deacon pours a sufficient quantity of hot water into the chalice cross-wise, saying:`,pointing:null,source_page:75,note:`ABSENT`},{id:`ef-28`,movement:`elevation_and_fraction`,speaker:`deacon`,mode:null,text:`The warmth of faith, full of the Holy Spirit. Amen.`,pointing:null,source_page:75,note:`ABSENT`},{id:`ef-29`,movement:`elevation_and_fraction`,speaker:`rubric`,text:`The deacon sets aside the hot water and stands aside.`,pointing:null,source_page:75,note:`ABSENT`},{id:`ef-30`,movement:`elevation_and_fraction`,speaker:`rubric`,text:`The priest breaks the portion XC into a number of pieces corresponding to the number of clergy who take part in the Liturgy.`,pointing:null,source_page:75,note:`ABSENT`},{id:`cc-01`,movement:`communion_of_clergy`,speaker:`priest`,mode:null,text:`Deacon, draw near.`,pointing:null,source_page:75,note:`Movement boundary confirmed under the ratified v5 rule — content-derived; no heading printed. This is where actual communing begins, distinguished from the fraction/arrangement rubrics preceding it.`},{id:`cc-02`,movement:`communion_of_clergy`,speaker:`rubric`,text:`The deacon approaches and bows, asking forgiveness; he then kisses the Holy Table and says:`,pointing:null,source_page:75,note:`ABSENT`},{id:`cc-03`,movement:`communion_of_clergy`,speaker:`deacon`,mode:null,text:`Give unto me, Master, the Precious and Holy Body of our Lord and God and Savior Jesus Christ.`,pointing:null,source_page:75,note:`ABSENT`},{id:`cc-04`,movement:`communion_of_clergy`,speaker:`rubric`,text:`Kissing the deacon's shoulder, the priest gives to him a portion of the Holy Bread, saying:`,pointing:null,source_page:75,note:`ABSENT`},{id:`cc-05`,movement:`communion_of_clergy`,speaker:`priest`,mode:null,text:`To the pious deacon ___, is given the Precious, Holy, and Most Pure Body of our Lord and God and Savior Jesus Christ, for the remission of his sins, and unto life everlasting.`,pointing:null,source_page:75,note:`ABSENT`},{id:`cc-06`,movement:`communion_of_clergy`,speaker:`rubric`,text:`The deacon kisses the priest's hand and shoulder as he receives the Holy Bread, and goes behind the Holy Table and prays with bowed head:`,pointing:null,source_page:75,note:`ABSENT`},{id:`cc-07`,movement:`communion_of_clergy`,speaker:`deacon`,mode:null,text:`I believe, O Lord, and I confess...`,pointing:null,source_page:75,note:`Page 75 ends here mid-prayer; the pre-communion prayer and communion of clergy continue on later pages, not yet provided.`},{id:`cc-08`,movement:`communion_of_clergy`,speaker:`rubric`,text:`As the priest takes a portion of the Holy Bread for himself, he prays:`,pointing:null,source_page:76,note:`ABSENT`},{id:`cc-09`,movement:`communion_of_clergy`,speaker:`priest`,mode:null,text:`The Precious and Most Holy Body of our Lord and God and Savior Jesus Christ is given unto me, the priest ___, for the remission of my sins, and unto life everlasting.`,pointing:null,source_page:76,note:`ABSENT`},{id:`cc-10`,movement:`communion_of_clergy`,speaker:`priest`,mode:null,text:`I believe, O Lord, and I confess that Thou art truly the Christ, the Son of the living God, Who camest into the world to save sinners, of whom I am first. I believe also that this is truly Thine Own Most Pure Body, and that this is truly Thine Own Precious Blood. Therefore, I pray Thee: have mercy upon me and forgive my transgressions both voluntary and involuntary, of word and of deed, committed in knowledge or in ignorance. And make me worthy to partake without condemnation of Thy Most Pure Mysteries, for the remission of my sins, and unto life everlasting. Amen.`,pointing:null,source_page:76,note:`Full text of the prayer the deacon began at cc-07, printed there only as an incipit + ellipsis. Same prayer, given in full here for the priest's own recitation.`},{id:`cc-11`,movement:`communion_of_clergy`,speaker:`priest`,mode:null,text:`Of Thy Mystical Supper, O Son of God, accept me today as a communicant; for I will not speak of Thy Mystery to Thine enemies, neither like Judas will I give Thee a kiss; but like the thief will I confess Thee: Remember me, O Lord, in Thy Kingdom.`,pointing:null,source_page:76,note:`ABSENT`},{id:`cc-12`,movement:`communion_of_clergy`,speaker:`priest`,mode:null,text:`May the communion of Thy Holy Mysteries be neither to my judgment nor to my condemnation, O Lord, but to the healing of soul and body.`,pointing:null,source_page:76,note:`ABSENT`},{id:`cc-13`,movement:`communion_of_clergy`,speaker:`rubric`,text:`Thus they partake of the Holy Bread with all fear and reverence. The priest then, takes the holy chalice in both hands with the veil and partakes of it thrice, saying:`,pointing:null,source_page:76,note:`ABSENT`},{id:`cc-14`,movement:`communion_of_clergy`,speaker:`priest`,mode:null,text:`The Precious and Most Holy Blood of our Lord, God and Savior Jesus Christ is partaken by me, the servant of God, priest ___, for the remission of my sins, and unto life everlasting. Amen.`,pointing:null,source_page:77,note:`ABSENT`},{id:`cc-15`,movement:`communion_of_clergy`,speaker:`rubric`,text:`The priest cleans the chalice and his lips with the veil, and says:`,pointing:null,source_page:77,note:`ABSENT`},{id:`cc-16`,movement:`communion_of_clergy`,speaker:`priest`,mode:null,text:`Lo, This has touched my lips, and shall take away my iniquities, and cleanse my sins.`,pointing:null,source_page:77,note:`ABSENT`},{id:`cc-17`,movement:`communion_of_clergy`,speaker:`rubric`,text:`The priest then summons the deacon:`,pointing:null,source_page:77,note:`ABSENT`},{id:`cc-18`,movement:`communion_of_clergy`,speaker:`priest`,mode:null,text:`Deacon, draw near.`,pointing:null,source_page:77,note:`ABSENT`},{id:`cc-19`,movement:`communion_of_clergy`,speaker:`rubric`,text:`The deacon approaches and bows once, saying:`,pointing:null,source_page:77,note:`ABSENT`},{id:`cc-20`,movement:`communion_of_clergy`,speaker:`deacon`,mode:null,text:`Lo, I draw near unto the Immortal King and our God. Give unto me, Master, the Precious and Holy Blood of our Lord and God and Savior Jesus Christ.`,pointing:null,source_page:77,note:`ABSENT`},{id:`cc-21`,movement:`communion_of_clergy`,speaker:`rubric`,text:`The priest holds the chalice and says:`,pointing:null,source_page:77,note:`ABSENT`},{id:`cc-22`,movement:`communion_of_clergy`,speaker:`priest`,mode:null,text:`The servant of God, deacon ___, partakes of the Precious and Holy Blood of our Lord and God and Savior Jesus Christ, for the remission of his sins, and unto life everlasting.`,pointing:null,source_page:77,note:`ABSENT`},{id:`cc-23`,movement:`communion_of_clergy`,speaker:`rubric`,text:`When the deacon has partaken, the priest says:`,pointing:null,source_page:77,note:`ABSENT`},{id:`cc-24`,movement:`communion_of_clergy`,speaker:`priest`,mode:null,text:`Lo, This has touched your lips, and shall take away your iniquities, and cleanse your sins.`,pointing:null,source_page:77,note:`ABSENT`},{id:`cf-01`,movement:`communion_of_faithful`,speaker:`rubric`,text:`The priest now divides the portions NI and KA of the Holy Lamb and puts them into the chalice for the communion of the people; the chalice is covered with a veil. Similarly, he lays the star-cover and the veils on the holy diskos. The Royal Doors are opened. The deacon, making a reverence, receives the chalice from the priest with devotion, goes through the doors, and elevating the holy chalice, shows it to the people, saying:`,pointing:null,source_page:77,note:`Movement boundary confirmed under the ratified v5 rule — content-derived; no heading printed. Text spans the page break (77→78).`},{id:`cf-02`,movement:`communion_of_faithful`,speaker:`deacon`,mode:null,text:`In the fear of God, and with faith, draw near!`,pointing:null,source_page:78,note:`ABSENT`},{id:`cf-03`,movement:`communion_of_faithful`,speaker:`choir`,text:`Blessèd is He that comes in the Name of the Lord! God is the Lord and has revealed Himself to us!`,pointing:null,source_page:78,note:`ABSENT`},{id:`cf-04`,movement:`communion_of_faithful`,speaker:`priest`,mode:null,cue:`(facing the people)`,text:`I believe, O Lord, and I confess...`,pointing:null,source_page:78,note:`Printed inline annotation '(facing the people)' — rendered verbatim as the cue. Abbreviated incipit + ellipsis again — full text is at cc-10.`},{id:`cf-05`,movement:`communion_of_faithful`,speaker:`rubric`,text:`When he has finished the Communion Prayer, the priest communicates those who are prepared to receive the Mystery, saying to each person:`,pointing:null,source_page:78,note:`ABSENT`},{id:`cf-06`,movement:`communion_of_faithful`,speaker:`priest`,mode:null,text:`The servant {{(or handmaid)}} of God ___, partakes of the Precious and Holy Body and Blood of our Lord and God and Savior Jesus Christ, for the remission of sins and unto life everlasting.`,pointing:null,source_page:78,note:`ABSENT`},{id:`cf-07`,movement:`communion_of_faithful`,speaker:`rubric`,text:`During the communion of the people, the choir sings:`,pointing:null,source_page:78,note:`ABSENT`},{id:`cf-08`,movement:`communion_of_faithful`,speaker:`choir`,text:`Receive the Body of Christ; taste the Fountain of Immortality. Alleluia! Alleluia! Alleluia!`,pointing:null,source_page:78,note:`ABSENT`},{id:`cf-09`,movement:`communion_of_faithful`,speaker:`rubric`,text:`The deacon cleans the lips of each communicant as he receives with the communion cloth. After all have been communicated, the celebrants return to the sanctuary and replace the chalice on the Holy Table. The deacon holds the diskos over the chalice as he says these Hymns of the Resurrection:`,pointing:null,source_page:78,note:`ABSENT`},{id:`cf-10`,movement:`communion_of_faithful`,speaker:`deacon`,mode:null,text:`Having beheld the Resurrection of Christ, let us worship the Holy Lord Jesus, the only Sinless One. We venerate Thy Cross, O Christ, and we praise and glorify Thy Holy Resurrection; for Thou art our God, and we know no other than Thee; we call on Thy Name. Come all you faithful, let us venerate Christ's Holy Resurrection! For, behold, through the Cross, joy has come into all the world. Let us ever bless the Lord, praising His Resurrection, for by enduring the Cross for us, He has destroyed death by death.`,pointing:null,source_page:78,note:`Text spans the page break (78→79).`},{id:`cf-11`,movement:`communion_of_faithful`,speaker:`deacon`,mode:null,text:`Shine! Shine! O New Jerusalem! The glory of the Lord has shone on you! Exult now and be glad, O Zion! Be radiant, O pure Theotokos, in the Resurrection of your Son!`,pointing:null,source_page:79,note:`ABSENT`},{id:`cf-12`,movement:`communion_of_faithful`,speaker:`deacon`,mode:null,text:`O Christ! Great and Most Holy Pascha! O Wisdom, Word, and Power of God! Grant that we may more perfectly partake of Thee in the never-ending Day of Thy Kingdom.`,pointing:null,source_page:79,note:`ABSENT`},{id:`cf-13`,movement:`communion_of_faithful`,speaker:`rubric`,text:`As the deacon thoroughly wipes the remaining particles from the diskos with the holy sponge into the chalice, he reverently says:`,pointing:null,source_page:79,note:`ABSENT`},{id:`cf-14`,movement:`communion_of_faithful`,speaker:`deacon`,mode:null,text:`Wash away, O Lord, the sins of all those who have been remembered here, by Thy Precious Blood; through the prayers of Thy saints.`,pointing:null,source_page:79,note:`ABSENT`},{id:`cf-15`,movement:`communion_of_faithful`,speaker:`rubric`,text:`The priest blesses the people exclaiming:`,pointing:null,source_page:79,note:`ABSENT`},{id:`cf-16`,movement:`communion_of_faithful`,speaker:`priest`,mode:`aloud`,text:`O God, save Thy people, and bless Thine inheritance.`,pointing:null,source_page:79,note:`ABSENT`},{id:`cf-17`,movement:`communion_of_faithful`,speaker:`choir`,text:`We have seen the true Light! We have received the heavenly Spirit! We have found the true Faith! Worshipping the undivided Trinity, Who has saved us.`,pointing:null,source_page:79,note:`ABSENT`},{id:`cf-18`,movement:`communion_of_faithful`,speaker:`rubric`,text:`The priest covers the chalice with one veil. He puts all others on the diskos. He censes the chalice three times saying quietly:`,pointing:null,source_page:79,note:`Text spans the page break (79→80).`},{id:`cf-19`,movement:`communion_of_faithful`,speaker:`priest`,mode:`quiet`,text:`Be Thou exalted, O God, above the heavens, and Thy glory over all the earth.`,pointing:null,source_page:80,note:`ABSENT`},{id:`cf-20`,movement:`communion_of_faithful`,speaker:`rubric`,text:`The priest gives the diskos to the deacon, and the deacon, taking it reverently, bows toward the faithful through the Royal Doors, saying nothing, he carries it with reverence to the Table of Oblation.`,pointing:null,source_page:80,note:`ABSENT`},{id:`cf-21`,movement:`communion_of_faithful`,speaker:`rubric`,text:`The priest takes the chalice in his right hand, and makes with it the Sign of the Cross over the Antimension, and says quietly to himself:`,pointing:null,source_page:80,note:`ABSENT`},{id:`cf-22`,movement:`communion_of_faithful`,speaker:`priest`,mode:`quiet`,text:`Blessèd is our God...`,pointing:null,source_page:80,note:`ABSENT`},{id:`cf-23`,movement:`communion_of_faithful`,speaker:`rubric`,text:`Then, holding the chalice, and facing the people, he says aloud:`,pointing:null,source_page:80,note:`ABSENT`},{id:`cf-24`,movement:`communion_of_faithful`,speaker:`priest`,mode:`aloud`,text:`Always, now and ever, and unto ages of ages.`,pointing:null,source_page:80,note:`ABSENT`},{id:`cf-25`,movement:`communion_of_faithful`,speaker:`rubric`,text:`The priest carries the chalice to the Table of Oblation as the deacon censes and then, receiving the censer, censes the chalice three times.`,pointing:null,source_page:80,note:`ABSENT`},{id:`cf-26`,movement:`communion_of_faithful`,speaker:`choir`,text:`Amen.`,pointing:null,source_page:80,note:`ABSENT`},{id:`cf-27`,movement:`communion_of_faithful`,speaker:`choir`,text:`Let our mouths be filled with Thy praise, O Lord, that we may sing of Thy glory; for Thou hast made us worthy to partake of Thy Holy, Divine, Immortal, and Life-creating Mysteries. Keep us in Thy holiness, that all the day we may meditate upon Thy righteousness. Alleluia! Alleluia! Alleluia!`,pointing:null,source_page:80,note:`ABSENT`},{id:`cf-28`,movement:`communion_of_faithful`,speaker:`rubric`,text:`The deacon goes through the north door to his usual place for the Litany; the priest returns to the Holy Table and again folds the Antimension.`,pointing:null,source_page:80,note:`ABSENT`},{id:`lt-heading`,movement:`thanksgiving_for_communion`,speaker:`heading`,text:`LITANY OF THANKSGIVING`,pointing:null,source_page:80,note:`ABSENT`},{id:`lt-01`,movement:`thanksgiving_for_communion`,speaker:`deacon`,mode:null,text:`Let us attend! Having partaken of the Divine, Holy, Most Pure, Immortal, Heavenly, Life-creating, and Awesome Mysteries of Christ, let us worthily give thanks unto the Lord.`,pointing:null,source_page:80,note:`Text spans the page break (80→81).`},{id:`lt-02`,movement:`thanksgiving_for_communion`,speaker:`choir`,text:`Lord, have mercy.`,pointing:null,source_page:81,note:`ABSENT`},{id:`lt-03`,movement:`thanksgiving_for_communion`,speaker:`deacon`,mode:null,text:`Help us, save us, have mercy on us, and keep us, O God, by Thy grace.`,pointing:null,source_page:81,note:`ABSENT`},{id:`lt-04`,movement:`thanksgiving_for_communion`,speaker:`choir`,text:`Lord, have mercy.`,pointing:null,source_page:81,note:`ABSENT`},{id:`lt-05`,movement:`thanksgiving_for_communion`,speaker:`deacon`,mode:null,text:`Asking that the whole day may be perfect, holy, peaceful, and sinless, let us commend ourselves and each other, and all our life unto Christ our God.`,pointing:null,source_page:81,note:`ABSENT`},{id:`lt-06`,movement:`thanksgiving_for_communion`,speaker:`choir`,text:`To Thee, O Lord.`,pointing:null,source_page:81,note:`ABSENT`},{id:`lt-07`,movement:`thanksgiving_for_communion`,speaker:`priest`,mode:`quiet`,text:`We thank Thee, O Master Who lovest mankind, Benefactor of our souls, that Thou hast made us worthy this day of Thy Heavenly and Immortal Mysteries. Make straight our path; strengthen us all in Thy fear; guard our life; make firm our steps; through the prayers and intercessions of the glorious Theotokos and Ever-Virgin Mary, and of all Thy saints.`,pointing:null,source_page:81,note:`Marked with '*' and '(131)'.`},{id:`lt-08`,movement:`thanksgiving_for_communion`,speaker:`rubric`,text:`The priest, having again folded the Antimension, makes the Sign of the Cross over it with the Holy Gospel as he exclaims:`,pointing:null,source_page:81,note:`ABSENT`},{id:`lt-09`,movement:`thanksgiving_for_communion`,speaker:`priest`,mode:`aloud`,text:`For Thou art our Sanctification, and unto Thee do we send up glory: to the Father, and to the Son, and to the Holy Spirit, now and ever, and unto ages of ages.`,pointing:null,source_page:81,note:`ABSENT`},{id:`lt-10`,movement:`thanksgiving_for_communion`,speaker:`choir`,text:`Amen.`,pointing:null,source_page:81,note:`ABSENT`},{id:`lt-11`,movement:`thanksgiving_for_communion`,speaker:`priest`,mode:null,text:`Let us depart in peace.`,pointing:null,source_page:81,note:`ABSENT`},{id:`lt-12`,movement:`thanksgiving_for_communion`,speaker:`choir`,text:`In the Name of the Lord.`,pointing:null,source_page:81,note:`ABSENT`},{id:`lt-13`,movement:`thanksgiving_for_communion`,speaker:`deacon`,mode:null,text:`Let us pray to the Lord.`,pointing:null,source_page:81,note:`ABSENT`},{id:`lt-14`,movement:`thanksgiving_for_communion`,speaker:`choir`,text:`Lord, have mercy.`,pointing:null,source_page:81,note:`ABSENT`},{id:`pba-heading`,movement:`prayer_behind_ambo`,speaker:`heading`,text:`PRAYER BEHIND THE AMVON`,pointing:null,source_page:82,note:`ABSENT`},{id:`pba-01`,movement:`prayer_behind_ambo`,speaker:`priest`,mode:null,text:`O Lord, Who blesses those who bless Thee, and sanctifiest those who trust in Thee: Save Thy people and bless Thine inheritance. Preserve the fullness of Thy Church. Sanctify those who love the beauty of Thy house; glorify them in return by Thy divine power, and forsake us not who put our hope in Thee. Give peace to Thy world, to Thy churches, to Thy priests, to all those in civil authority, and to all Thy people. For every good and every perfect gift is from above, coming down from Thee, the Father of Lights, and unto Thee we send up glory, thanksgiving and worship: to the Father, and to the Son, and to the Holy Spirit, now and ever, and unto ages of ages.`,pointing:null,source_page:82,note:`ABSENT`},{id:`pba-02`,movement:`prayer_behind_ambo`,speaker:`choir`,text:`Amen.`,pointing:null,source_page:82,note:`ABSENT`},{id:`pba-03`,movement:`prayer_behind_ambo`,speaker:`choir`,text:`Blessèd be the Name of the Lord, henceforth and forevermore. {{(3)}}`,pointing:null,source_page:82,note:`ABSENT`},{id:`pba-04`,movement:`prayer_behind_ambo`,speaker:`rubric`,text:`And the choir continues with Psalm 33 (34): 'I will bless the Lord….' The deacon, holding the orarion, stands with bowed head before the icon of our Lord Christ until the completion of the prayer behind the amvon. The priest enters the sanctuary through the Royal Doors.`,pointing:null,source_page:82,note:`ABSENT`},{id:`pba-05`,movement:`prayer_behind_ambo`,speaker:`rubric`,text:`The deacon, after entering through the north door, kneels at the north side of the Holy Table, while the priest says quietly the following prayer over him and blesses him:`,pointing:null,source_page:82,note:`ABSENT`},{id:`pba-06`,movement:`prayer_behind_ambo`,speaker:`priest`,mode:`quiet`,text:`O Christ our God, Who art Thyself the fulfillment of the law and the prophets, Who didst fulfill all the dispensation of the Father: fill our hearts with joy and gladness always, now and ever, and unto ages of ages. Amen.`,pointing:null,source_page:82,note:`Marked with '*' and '(132)'.`},{id:`di-01`,movement:`dismissal`,speaker:`rubric`,text:`After hearing this prayer, the deacon goes to the Table of Oblation and consumes the Holy Gifts with all reverence and awe.`,pointing:null,source_page:83,note:`ABSENT`},{id:`di-02`,movement:`dismissal`,speaker:`rubric`,text:`The priest blesses the people, saying:`,pointing:null,source_page:83,note:`ABSENT`},{id:`di-03`,movement:`dismissal`,speaker:`priest`,mode:null,text:`The blessing of the Lord be upon you through His grace and love for mankind always, now and ever, and unto ages of ages.`,pointing:null,source_page:83,note:`ABSENT`},{id:`di-04`,movement:`dismissal`,speaker:`choir`,text:`Amen.`,pointing:null,source_page:83,note:`ABSENT`},{id:`di-heading`,movement:`dismissal`,speaker:`heading`,text:`DISMISSAL`,pointing:null,source_page:83,note:`ABSENT`},{id:`di-05`,movement:`dismissal`,speaker:`priest`,mode:null,text:`Glory to Thee, O Christ God, our Hope, glory to Thee!`,pointing:null,source_page:83,note:`ABSENT`},{id:`di-06`,movement:`dismissal`,speaker:`choir`,text:`Glory to the Father, and to the Son, and to the Holy Spirit, now and ever, and unto ages of ages. Amen.`,pointing:null,source_page:83,note:`ABSENT`},{id:`di-07`,movement:`dismissal`,speaker:`choir`,text:`Lord have mercy. {{(3)}} Father, bless.`,pointing:null,source_page:83,note:`ABSENT`},{id:`di-08`,movement:`dismissal`,speaker:`priest`,mode:null,text:`May {{[He Who rose from the dead]}} Christ our true God, through the prayers of His most pure Mother; of the holy, glorious, and all-laudable apostles; of our father among the saints, John Chrysostom, Archbishop of Constantinople; of Saint{{(s)}} ___ {{(of the Church)}}; of Saint ___ {{(of the day)}} whom we commemorate today; of the holy and righteous ancestors of God, Joachim and Anna; and of all the saints: have mercy on us and save us, for He is good and loveth mankind.`,pointing:null,source_page:83,note:`'[He Who rose from the dead]' is a day-variant clause (this is the Sunday form; a footnote points to Appendix III for other days) — same pattern as the Entrance Hymn's day-type variant (le-10/le-11). RESOLVED (spec v8): captured verbatim as printed; day-type resolution is intentionally out of scope for this module, left to whatever integrates it into the Hours tool.`},{id:`di-09`,movement:`dismissal`,speaker:`choir`,text:`Amen.`,pointing:null,source_page:83,note:`ABSENT`},{id:`di-10`,movement:`dismissal`,speaker:`rubric`,text:`And the choir now sings the Many Years.`,pointing:null,source_page:83,note:`ABSENT`},{id:`di-11`,movement:`dismissal`,speaker:`rubric`,text:`The people come to venerate the Cross and receive the Antidoron. Those who received the Holy Mysteries now listen as the Prayers of Thanksgiving are read (See Appendix II).`,pointing:null,source_page:83,note:`ABSENT`},{id:`di-footnote`,movement:`dismissal`,speaker:`rubric`,text:`On Sunday. For Dismissals used on other days, See Appendix III.`,pointing:null,source_page:83,note:`ABSENT`},{id:`atd-heading`,movement:`after_the_dismissal`,speaker:`heading`,text:`AFTER THE DISMISSAL`,pointing:null,source_page:84,note:`ABSENT`},{id:`atd-01`,movement:`after_the_dismissal`,speaker:`rubric`,text:`The priest returns to the sanctuary, says the Prayers of Thanksgiving (Appendix II) and removing his priestly vestments prays:`,pointing:null,source_page:84,note:`ABSENT`},{id:`atd-heading2`,movement:`after_the_dismissal`,speaker:`heading`,text:`St. Symeon's Prayer`,pointing:null,source_page:84,note:`ABSENT`},{id:`atd-02`,movement:`after_the_dismissal`,speaker:`priest`,mode:null,text:`Lord, now lettest Thou Thy servant depart in peace, according to Thy word. For mine eyes have seen Thy salvation, which Thou hast prepared before the face of all people: a light to enlighten the Gentiles, and the glory of Thy people, Israel.`,pointing:null,source_page:84,note:`No speaker label printed before this text — assigned to priest per the preceding rubric, not an explicit printed label.`},{id:`atd-heading3`,movement:`after_the_dismissal`,speaker:`heading`,text:`Trisagion Prayers`,pointing:null,source_page:84,note:`ABSENT`},{id:`atd-03`,movement:`after_the_dismissal`,speaker:`priest`,mode:null,text:`Holy God! Holy Mighty! Holy Immortal! Have mercy on us. {{(3)}}`,pointing:null,source_page:84,note:`No label printed; continuing the priest's private prayer.`},{id:`atd-04`,movement:`after_the_dismissal`,speaker:`priest`,mode:null,text:`Glory to the Father, and to the Son, and to the Holy Spirit, now and ever, and unto ages of ages. Amen.`,pointing:null,source_page:84,note:`ABSENT`},{id:`atd-05`,movement:`after_the_dismissal`,speaker:`priest`,mode:null,text:`Most Holy Trinity have mercy on us; Lord, cleanse our sins; Master, pardon our transgressions; Holy One, visit and heal our infirmities, for Thy Name's sake.`,pointing:null,source_page:84,note:`ABSENT`},{id:`atd-06`,movement:`after_the_dismissal`,speaker:`priest`,mode:null,text:`Lord, have mercy. {{(3)}}`,pointing:null,source_page:84,note:`ABSENT`},{id:`atd-07`,movement:`after_the_dismissal`,speaker:`priest`,mode:null,text:`Glory to the Father, and to the Son, and to the Holy Spirit, now and ever, and unto ages of ages. Amen.`,pointing:null,source_page:84,note:`ABSENT`},{id:`atd-08`,movement:`after_the_dismissal`,speaker:`priest`,mode:null,text:`Our Father, Who art in heaven, hallowed be Thy Name. Thy Kingdom come. Thy Will be done, on earth as it is in heaven. Give us this day our daily bread; and forgive us our trespasses, as we forgive those who trespass against us; and lead us not into temptation, but deliver us from the evil one.`,pointing:null,source_page:84,note:`Text spans the page break (84→85).`},{id:`atd-09`,movement:`after_the_dismissal`,speaker:`priest`,mode:null,text:`For Thine is the Kingdom, and the power, and the glory: of the Father, and of the Son, and of the Holy Spirit, now and ever, and unto ages of ages. Amen.`,pointing:null,source_page:85,note:`ABSENT`},{id:`atd-heading4`,movement:`after_the_dismissal`,speaker:`heading`,text:`AT THE LITURGY OF SAINT JOHN CHRYSOSTOM`,pointing:null,source_page:85,note:`ABSENT`},{id:`atd-heading5`,movement:`after_the_dismissal`,speaker:`heading`,text:`TROPARION:`,pointing:null,source_page:85,note:`ABSENT`},{id:`atd-10`,movement:`after_the_dismissal`,speaker:`choir`,text:`Grace shining forth from your lips like a beacon has enlightened the universe. It has shown to the world the riches of poverty. It has revealed to us the heights of humility. Teaching us by your words, O father John the Golden-mouth, intercede before the Word, Christ our God, to save our souls.`,pointing:null,source_page:85,note:`Speaker inferred as choir — source labels this and the hymns below by genre ('TROPARION:'/'KONTAKION:'/'THEOTOKION:'), not by performer. Marked with '*' and '(132)'.`},{id:`atd-11`,movement:`after_the_dismissal`,speaker:`choir`,text:`Glory to the Father, and to the Son, and to the Holy Spirit:`,pointing:null,source_page:85,note:`ABSENT`},{id:`atd-heading6`,movement:`after_the_dismissal`,speaker:`heading`,text:`KONTAKION:`,pointing:null,source_page:85,note:`ABSENT`},{id:`atd-12`,movement:`after_the_dismissal`,speaker:`choir`,text:`You received divine grace from heaven, and by your lips you teach all to worship the One God in Trinity, O John Chrysostom, all-blessèd saint. Worthily do we extol you, for you are a teacher who makes clear the things divine.`,pointing:null,source_page:85,note:`ABSENT`},{id:`atd-13`,movement:`after_the_dismissal`,speaker:`choir`,text:`Now and ever, and unto ages of ages. Amen.`,pointing:null,source_page:85,note:`ABSENT`},{id:`atd-heading7`,movement:`after_the_dismissal`,speaker:`heading`,text:`THEOTOKION:`,pointing:null,source_page:85,note:`ABSENT`},{id:`atd-14`,movement:`after_the_dismissal`,speaker:`choir`,text:`Steadfast protectress of Christians, constant advocate before the Creator: despise not the cry of us sinners, but in your goodness come speedily to help us who call on you in faith. Hasten to hear our petition and to intercede for us, O Theotokos, for you always protect those who honor you.`,pointing:null,source_page:85,note:`ABSENT`},{id:`atd-15`,movement:`after_the_dismissal`,speaker:`choir`,text:`Lord, have mercy! {{(12)}}`,pointing:null,source_page:85,note:`ABSENT`},{id:`atd-16`,movement:`after_the_dismissal`,speaker:`choir`,text:`More honorable than the Cherubim, and more glorious beyond compare than the Seraphim: without defilement you gave birth to God the Word. True Theotokos, we magnify you.`,pointing:null,source_page:86,note:`Reprise of the second half of 'It is Truly Meet' (cf. cm-07), reused here as part of the closing devotions.`},{id:`atd-17`,movement:`after_the_dismissal`,speaker:`choir`,text:`Glory to the Father, and to the Son, and to the Holy Spirit, now and ever, and unto ages of ages. Amen.`,pointing:null,source_page:86,note:`ABSENT`},{id:`atd-18`,movement:`after_the_dismissal`,speaker:`rubric`,text:`The priest pronounces the dismissal.`,pointing:null,source_page:86,note:`ABSENT`},{id:`atd-19`,movement:`after_the_dismissal`,speaker:`rubric`,text:`The deacon consumes the Holy Things with all diligence, so that no slightest particle fall or remain, pours water and wine into the holy chalice, consumes it, and absorbs all moisture with the sponge, and sets the holy vessels together, wraps them and puts them in their usual place, saying: 'Lord, now lettest Thou Thy servant depart…' and the rest, as does the priest, and he washes his hands in the usual place, and makes a reverence together with the priest. The dismissal is given, and giving thanks to God, they go their way.`,pointing:null,source_page:86,note:`ABSENT`},{id:`atd-20`,movement:`after_the_dismissal`,speaker:`rubric`,text:`Thus concludes the Divine Liturgy of St. John Chrysostom.`,pointing:null,source_page:86,note:`Followed by a decorative row of three small red cross ornaments in the source, marking the physical end of the text — not transcribed as a content unit.`}],t={"lc-16":{status:`encoded`,basil_page:115,mode:`quiet`,text:`O Lord our God, Who dwellest in the heavens and regardest all Thy works: Look down on Thy servants the catechumens, who have bowed their necks before Thee. Grant them a light yoke; make them honorable members of Thy holy Church; make them worthy of the laver of regeneration, the remission of sins, and the robe of incorruption — for the knowledge of Thee, our true God.`,note:`Basil's Prayer for the Catechumens (Appendix IV, p.115, cites back to Chrysostom p.48-49). Confirmed genuinely different text, not a reprint. Its Exclamation is worded identically to Chrysostom's (lc-17/lc-18) — not overridden.`},"lf1-02":{status:`encoded`,basil_page:115,mode:`quiet`,text:`Thou, O Lord, hast revealed to us this great Mystery of salvation. Thou hast enabled us, Thy humble servants, to be ministers at Thy holy altar. By the power of Thy Holy Spirit, enable us also to perform this service; so that standing blamelessly before Thy holy glory, we may offer Thee a sacrifice of praise. For Thou alone accomplishest all things in all men. May our sacrifice be acceptable and well-pleasing in Thy sight, O Lord, for our sins and for the errors of all Thy people.`,note:`Basil's First Prayer of the Faithful (Appendix IV, p.115-116, cites Chrysostom p.49). Confirmed different text. Exclamation identical to Chrysostom's (lf1-06/lf1-07) — not overridden.`},"lf2-15":{status:`encoded`,basil_page:116,mode:`quiet`,text:`O God, Who in mercy and compassion hast visited our lowliness; Who hast set us, Thy humble and sinful and unworthy servants, to serve at Thy holy altar before Thy holy glory. By the power of Thy Holy Spirit, strengthen us for this service; and grant speech to our lips so that we may call down the grace of Thy Holy Spirit upon the gifts that are about to be offered.`,note:`Basil's Second Prayer of the Faithful (Appendix IV, p.116, cites Chrysostom p.51). Confirmed different text. Exclamation identical to Chrysostom's (lf2-18/lf2-19) — not overridden.`},"los-10":{status:`encoded`,basil_page:117,mode:`quiet`,text:`O Lord, our God, Who hast created us and brought us into this life; Who hast shown us the ways to salvation, and bestowed on us the revelation of heavenly Mysteries: Thou art the One Who has appointed us to this service in the power of Thy Holy Spirit. Therefore, O Lord, enable us to be ministers of Thy new Testament and servants of Thy Holy Mysteries. Through the greatness of Thy mercy, accept us as we draw near to Thy holy altar, so that we may be worthy to offer to Thee this reasonable and bloodless sacrifice for our sins and for the errors of Thy people. Having received it upon Thy holy, heavenly and ideal altar as a sweet spiritual fragrance, send down upon us in return the grace of Thy Holy Spirit. Look down on us, O God, and behold this our service. Receive it as thou didst receive the gifts of Abel, the sacrifices of Noah, the priestly offices of Moses and Aaron, and the peace-offerings of Samuel. Even as Thou didst receive from Thy holy apostles this true worship, so now, in Thy goodness, accept these gifts from the hands of us sinners, O Lord; that having been accounted worthy to serve without offence at Thy holy altar, we may receive the reward of wide and faithful stewards on the awesome day of Thy just retribution.`,note:`Basil's Prayer of the Prothesis/Offertory (Appendix IV, p.117-118, cites Chrysostom p.57). Confirmed different text — much longer, with the Abel/Noah/Moses/Samuel typology not present in Chrysostom's version. 'wide and faithful stewards' transcribed as read; possibly 'wise' (cf. Luke 12:42) — flagged for verification against the physical page, not silently corrected. Exclamation identical to Chrysostom's — not overridden.`},"ap-02":{status:`encoded`,basil_page:118,mode:`quiet`,text:`O Existing One, Master, Lord God, Father almighty and adorable! It is truly meet and right and befitting the magnificence of Thy holiness to praise Thee, to sing to Thee, to bless Thee, to worship Thee, to give thanks to Thee, to glorify Thee — the only truly existing God — and to offer to Thee this our reasonable worship with a contrite heart and a spirit of humility, for Thou hast granted us the knowledge of Thy truth. Who can utter Thy mighty acts? Or make all Thy praises known? Or tell of all Thy miracles at all times? O Master of all, Lord of heaven and earth and of all creation, both visible and invisible, incomprehensible, indescribable, changeless. O Father of our Lord Jesus Christ, the great God and Savior, our hope, Who is the image of Thy goodness, the seal of Thy very likeness, showing forth in Himself Thee, O Father — the living Word, the true God, the eternal Wisdom, the Life, the Sanctification, the Power, the true Light, through Whom the Holy Spirit was revealed — the Spirit of truth, the gift of sonship, the pledge of future inheritance, the first fruits of eternal blessings, the life-creating power, the fountain of sanctification, through Whom every creature of reason and understanding worships Thee and always sings to Thee a hymn of glory, for all things are Thy servants. Thou art praised by angels, archangels, thrones, dominions, principalities, authorities, powers, and many-eyed Cherubim. 'Round about Thee stand the Seraphim, one with six wings and the other with six wings; with two they cover their faces, with two they cover their feet, and with two they fly, crying one to another with unceasing voices and ever-resounding praises:`,note:`Basil, Appendix IV pp.118-119 (The Anaphora, opening). Far longer than Chrysostom's ap-02, as expected — this is Basil's famously extended anaphoral preface. Ends immediately before the Sanctus Exclamation, which (like the Sanctus response itself) is shared text — not overridden.`},"ai-02":{status:`encoded`,basil_page:120,mode:`quiet`,text:`With these blessèd powers, O Master Who lovest mankind, we sinners also cry aloud and say: Holy art Thou — truly Most Holy — and there are no bounds to the magnificence of Thy holiness. Thou art gracious in all Thy deeds, for with righteousness and true judgment Thou hast ordered all things for us. When Thou didst create man by taking dust from the earth, and didst honor him with Thine own image, O God, Thou didst set him in a paradise of delight, promising him eternal life and the enjoyment of everlasting blessings in the observance of Thy commandments. But when man disobeyed Thee, the true God Who had created them, and was deceived by the guile of the serpent, becoming subject to death through his own transgressions, Thou, O God, in Thy righteous judgment, didst send him forth from paradise into this world, returning him to the earth from which he was taken, yet providing for him the salvation of regeneration in Thy Christ Himself. For Thou didst not turn Thyself away forever from Thy creature, Whom Thou hadst made, O Good One, nor didst Thou forget the work of Thy hands. Through the tender compassion of Thy mercy, Thou didst visit him in various ways: Thou didst send prophets; Thou didst perform mighty works by Thy saints, who in every generation were well-pleasing to Thee; Thou didst speak to us by the mouth of Thy servants the prophets, foretelling to us the salvation which was to come; Thou didst give us the law as a help; Thou didst appoint angels as guardians. And when the fullness of time had come, Thou didst speak to us through Thy Son Himself, by Whom Thou didst also make the ages; Who, being the Radiance of Thy Glory and the Image of Thy Person, upholding all things by the word of His power, thought it not robbery to be equal to Thee, the God and Father. He was God before the ages, yet He appeared on earth and lived among men, becoming incarnate of a holy Virgin; He emptied Himself, taking the form of a servant, being likened to the body of our lowliness, that He might liken us to the image of His glory. For as by man sin entered into the world, and by sin death, so it pleased Thine Only-begotten Son, Who was in the bosom of Thee, the God and Father, Who was born of a woman, the Holy Theotokos and Ever-Virgin Mary, Who was born under the law, to condemn sin in His flesh, so that those who were dead in Adam might be made alive in Thy Christ Himself. He lived in this world and gave us commandments of salvation; releasing us from the delusions of idolatry, He brought us to knowledge of Thee, the true God and Father. He obtained us for His own chosen people, a royal priesthood, a holy nation. Having cleansed us in water, and sanctified us with the Holy Spirit, He gave Himself as a ransom to death, in which we were held captive, sold under sin. Descending through the Cross into hell — that He might fill all things with Himself — He loosed the pangs of death. He arose on the third day, having made for all flesh a path to the resurrection from the dead, since it was not possible for the Author of Life to be a victim of corruption. So He became the first-fruits of those who have fallen asleep, the first-born of the dead, that He might be Himself truly the first in all things. Ascending into Heaven, He sat down at the right hand of Thy majesty on high, and He will come to render to every man according to his works. And as memorials of His saving Passion, He has left us these Things, which we have set forth according to His command. For when He was about to go forth to His voluntary and ever-memorable and Life-creating death — in the night in which He gave Himself up for the life of the world — He took bread into His holy and pure hands; and having shown it to Thee, the God and Father, having given thanks, blessed and hallowed it, and broken it,`,note:`Basil, Appendix IV pp.120-122 (Institution narrative, quiet prayer). Confirmed different from Chrysostom's ai-02 — Basil's version carries the full creation/fall/redemption narrative. Ends one clause earlier than Chrysostom's does, at 'and broken it,' — the clause 'He gave it to His holy disciples and apostles, saying:' moves into the Exclamation (ai-04) in Basil. Three source typos corrected on Bill's instruction: 'who is every generation' → 'who in every generation'; 'though it not robbery' → 'thought it not robbery'; 'in the bosom the Thee' → 'in the bosom of Thee'.`},"ai-04":{status:`encoded`,basil_page:122,mode:`aloud`,text:`He gave it to His holy disciples and apostles, saying: Take! Eat! This is My Body which is broken for you, for the remission of sins.`,note:`Basil, Appendix IV p.122 (Exclamation at the bread). NEW divergence — carries no asterisk marker in Chrysostom, the same blind spot that originally hid ef-02. Basil's quiet prayer (ai-02) stops at 'and broken it,', so the clause 'He gave it to His holy disciples and apostles, saying:' is spoken aloud here rather than quietly. Falsifies the v15 working default that every Exclamation is worded identically between the two Liturgies. Punctuation normalized to Chrysostom's on Bill's instruction (Basil prints 'My Body, which is broken for you for the remission of sins.'; Chrysostom's comma placement and terminal mark kept instead).`},"ai-07":{status:`encoded`,basil_page:122,mode:`quiet`,cue:`(quietly)`,text:`Likewise He took the cup of the fruit of the vine, and having mingled it and given thanks, blessed and hallowed it,`,note:`Basil, Appendix IV p.122 (quiet prayer at the cup). NEW divergence — no asterisk marker in Chrysostom. Genuinely different wording, not merely a moved clause: Chrysostom reads 'And likewise, after supper, He took the cup, saying:'. Basil ends at 'hallowed it,' and moves 'He gave it to His holy disciples and apostles, saying:' into the Exclamation (ai-09).`},"ai-09":{status:`encoded`,basil_page:122,mode:`aloud`,text:`He gave it to His holy disciples and apostles, saying: Drink of it, all of you! This is My Blood of the New Testament, which is shed for you and for many, for the remission of sins!`,note:`Basil, Appendix IV p.122 (Exclamation at the cup). Marked with '*' and '(122)' in Chrysostom. Basil prepends 'He gave it to His holy disciples and apostles, saying:', which Chrysostom speaks quietly at the end of ai-07. Terminal '!' follows Chrysostom on Bill's instruction (Basil prints a period).`},"aa-02":{status:`encoded`,basil_page:123,mode:`quiet`,text:`Do this in remembrance of Me! For as often as you eat this Bread and drink this Cup, you proclaim My Death, you confess My Resurrection! Therefore, we also, O Master, remembering His saving Passion and Life-creating Cross, His three-day Burial and Resurrection from the dead, His Ascension into heaven and sitting at the right hand of the God and Father, and His glorious and awesome Second Coming,`,note:`Basil, Appendix IV p.123 (Anamnesis). Marked with '*' and '(123)' in Chrysostom. Confirmed different — Basil opens with the dominical command ('Do this in remembrance of Me!') and the Pauline proclamation before the anamnetic list, neither of which Chrysostom's aa-02 carries. Ends mid-sentence at 'Second Coming,', running on into the Exclamation (aa-04), which is shared.`},"ae-02":{status:`encoded`,basil_page:123,mode:`quiet`,text:`Therefore, Most Holy Master, we also Thy sinful and unworthy servants, whom Thou hast permitted to serve at Thy holy altar not because of our own righteousness (for we have done nothing good upon the earth), but because of Thy mercy and compassions (which Thou hast so richly poured out on us), we now dare to approach Thy holy altar and, offering to Thee the antitypes of the Holy Body and Blood of Thy Christ, we pray Thee and call upon Thee, O Holy of Holies, that by the favor of Thy goodness Thy Holy Spirit may come upon us and upon the gifts now offered to bless, to hallow, and to show.`,note:`Basil, Appendix IV p.123 (Epiclesis). Marked with '*' and '(123)' in Chrysostom. Confirmed different — Basil's epiclesis is far longer and turns on 'the antitypes of the Holy Body and Blood', language absent from Chrysostom's ae-02. One source typo corrected in line with the ai-02 corrections: 'which thou hast so richly poured out' → 'which Thou hast'; every other second-person pronoun on the page is capitalized. Basil's following rubric reads 'And the priest continues:' where Chrysostom's ae-03 reads 'The priest and the deacon bow three times before the Holy Table as they say:' — rubric left inherited, not overridden.`},"ae-12":{status:`encoded`,basil_page:124,text:`This Bread to be the Precious Body of our Lord and God and Savior Jesus Christ.`,note:`Basil, Appendix IV p.124 (consecration of the Bread). NEW divergence — no asterisk marker in Chrysostom, whose ae-12 reads 'And make this Bread the Precious Body of Thy Christ.' Basil names the Lord in full and drops the imperative 'make', the two formulae differing in substance and not only in wording. Encoded under the Option A rule (unmarked divergences are overridden so a Basil render reproduces the appendix).`},"ae-17":{status:`encoded`,basil_page:124,text:`And this Cup to be the Precious Blood of our Lord and God and Savior Jesus Christ.`,note:`Basil, Appendix IV p.124 (consecration of the Cup). NEW divergence — no asterisk marker in Chrysostom, whose ae-17 reads 'And that which is in this Cup, the Precious Blood of Thy Christ.' Basil prints a further priest line, 'Shed for the life of the world.', between the deacon's Amen (ae-18) and 'Bless both, Master' (ae-20); it has no counterpart unit in Chrysostom, so it is carried as BASIL_INSERTS['b-ae-18a'] rather than folded into this override.`},"cm-02":{status:`encoded`,basil_page:125,mode:`quiet`,text:`And unite all of us to one another who become partakers of the One Bread and Cup in the communion of the Holy Spirit. Grant that none of us may partake of the Holy Body and Blood of Thy Christ or judgment or condemnation.`,note:`Basil, Appendix IV p.125. Confirmed different from Chrysostom's cm-02.`},"cm-03":{status:`encoded`,basil_page:125,mode:`quiet`,text:`Instead, may we find mercy and grace with all the saints who through the ages have been well-pleasing to Thee: ancestors, fathers, patriarchs, prophets, apostles, preachers, evangelists, martyrs, confessors, teachers, and every righteous spirit made perfect in faith.`,note:`Basil, Appendix IV p.125. New divergence, not in Chrysostom's own markers — natural continuation of cm-02's sentence in Basil's text.`},"cm-09":{status:`encoded`,basil_page:126,mode:`quiet`,text:`With the holy Prophet, Forerunner, and Baptist John; the holy, glorious, and all-laudable apostles; Saint ___ {{(of the day)}} whom we commemorate today; and with all Thy saints. By their prayers, visit us, O God. For the salvation, visitation, and remission of sins, of the servants of God ___. Remember all those who have fallen asleep before us in the hope of resurrection to eternal life, especially ___; grant them rest in forgiveness of soul, O our God, in a place where there is no sighing or sorrow, but where the Light of Thy countenance shines on them.`,note:`Basil, Appendix IV p.126. Longer than Chrysostom's cm-09 — adds a sentence for the living ('servants of God ___') not present in Chrysostom's version.`},"cm-10":{status:`encoded`,basil_page:126,mode:`quiet`,text:`Again we entreat Thee: Remember, O Lord, Thy Holy, Catholic, and Apostolic Church, which is from end to end of the universe; give peace to Her whom Thou hast obtained with the Precious Blood of Thy Christ; also preserve this holy temple until the end of the world. Remember, O Lord, those who offered Thee these Gifts, and those for whom and through whom they offered them, and their intentions. Remember, O Lord, those who bring offerings and do good in Thy Holy Churches, and those who remember the poor; reward them with Thy rich and heavenly gifts; for their earthly, temporal, and corruptible gifts, do Thou grant them Thy heavenly ones, eternal and incorruptible. Remember, O Lord, those who are in the deserts, mountains, caverns and pits of the earth. Remember, O Lord, those who live in chastity and godliness, in austerity and holiness of life.`,note:`Basil, Appendix IV p.126. First of four editorial units (cm-10, cm-11, b-cm-11a, b-cm-11b) carved from one continuous printed paragraph (pp.126-128) that Basil says before the 'Among the first' Exclamation; the source prints no break, and the split follows its own 'Remember, O Lord' sentence starts (spec v20). Replaces Chrysostom's Episcopate petition in this slot only positionally: Basil says its Episcopate prayer AFTER the Exclamation (see cm-16).`},"cm-11":{status:`encoded`,basil_page:126,mode:`quiet`,text:`Remember, O Lord, this country and all civil authorities; grant them a secure and lasting peace; speak good things into their hearts concerning Thy Church and all Thy people, that we, in their tranquility, may lead a calm and peaceful life in all godliness and sanctity. Remember, O Lord, every principality and authority; our brothers who serve in the government and the armed forces. Preserve the good in goodness, and make the evil be good by Thy goodness. Remember, O Lord, the people here present and those who are absent for honorable reasons. Have mercy on them and on us according to the multitude of Thy mercies. Fill their treasuries with every good thing; preserve their marriages in peace and harmony; raise the infants; guide the young; support the aged; encourage the faint-hearted; reunite the separated; lead back those who are in error and join them to Thy Holy, Catholic, and Apostolic Church; free those who are held captive by unclean spirits; sail with those who sail; travel with those who travel by land and by air; defend the widows; protect the orphans; free the captives; heal the sick.`,note:`Basil, Appendix IV pp.126-127. Second of four editorial units from the continuous pp.126-128 paragraph (spec v20); runs from the page-126 line 'Remember, O Lord, this country' to 'heal the sick.' on p.127. Thematic match to Chrysostom's cm-11 (civil authorities). One source typo corrected on Bill's approval: p.127 'Thy Church an all Thy people' encoded as 'and'.`},"cm-16":{status:`encoded`,basil_page:128,mode:`quiet`,cue:`(quietly)`,text:`Remember, O Lord, all the Orthodox Episcopate, who rightly divide the word of Thy truth. Remember, O Lord, my unworthiness also, by the multitude of Thy compassions; forgive my every transgression, both voluntary and involuntary. Because of my sins, do not withhold the grace of Thy Holy Spirit from these Gifts here set forth. Remember, O Lord, the priesthood, the diaconate in Christ, and every order of the clergy.`,note:`Basil, Appendix IV p.128, the priest's quiet prayer after the 'Among the first' Exclamation. Marked with '*' and '(128)' in Chrysostom. REPLACES the v16 override, which held the 'Deliver this city' sentence: that sentence is said BEFORE the Exclamation in Basil and now lives in b-cm-11b (spec v20). Basil's Episcopate petition sits here, where Chrysostom's is before the Exclamation (cm-10). Continues on p.129 as b-cm-16a. Cue '(quietly)' as printed. One source typo corrected on Bill's approval: 'the word of thy truth' encoded as 'Thy', per the p.123 register rule.`},"lblp-02":{status:`encoded`,basil_page:129,mode:null,text:`And may the mercies of our great God and Savior Jesus Christ be with you all.`,note:`Basil, Appendix IV p.129, the blessing after the Commemorations' final Amen. No asterisk marker in Chrysostom, whose lblp-02 (p.69) reads 'be with all of you.' Same words, different order: more than the v19 'typesetting, not substance' rule covers, so overridden verbatim-first on Bill's decision (spec v20). The choir's 'And with your spirit.' (lblp-03) is identical and stays shared.`},"lblp-14":{status:`encoded`,basil_page:129,mode:`quiet`,text:`O our God, the God of salvation, do Thou teach us to thank Thee worthily for the benefits which Thou hast performed for us and still performest with us. Having accepted these gifts, O our God, do Thou purify us form every defilement of flesh and spirit, and teach us how to perfect our sanctification in Thy fear, so that receiving a portion of Thy Holy Things with a pure conscience we may be united with the Holy Body and Blood of Thy Christ. Having received them worthily, may we have Christ dwelling in our hearts, and may we become the Temple of Thy Holy Spirit. Yes, O our God, let none of us be guilty of these, Thine Awesome and Heavenly Mysteries, nor be infirm in soul and body by partaking of them unworthily. But, enable us, even to our last breath, to receive a portion of Thy Holy Things, worthily, as a support on the road to eternal life and an acceptable defense at the dread judgment seat of Thy Christ. That we also, together with all the saints who through the ages have been well-pleasing to Thee, may become partakers of Thy eternal good things, which Thou hast prepared for those who love Thee, O Lord.`,note:`Basil, Appendix IV pp.129-130 ("Prayer Before Our Father"). 'purify us form every defilement' transcribed as printed — likely 'from', flagged not corrected.`},"boh-06":{status:`encoded`,basil_page:130,mode:`quiet`,text:`O Master, Lord, Father of compassions and God of every consolation: Bless, sanctify, guard, strengthen, and confirm those who have bowed their heads to Thee. Withdraw them from every evil deed; apply them to every good work and make them worthy to partake without condemnation of these, Thy Most Pure and Life-creating Mysteries, for remission of sins and for the communion of the Holy Spirit.`,note:`Basil, Appendix IV p.130 ("Prayer After Our Father").`},"lt-07":{status:`encoded`,basil_page:131,mode:`quiet`,text:`We thank Thee, O Lord, our God, for the participation in Thy Holy, Most Pure, Immortal and Heavenly Mysteries, which Thou hast granted us for the good and sanctification and healing of our souls and bodies. Do Thou, O Master of all, grant that the communion of the Holy Body and Blood of Thy Christ may be to us for a faith unashamed, a love unfeigned, an increase of wisdom, the healing of soul and body, the repelling of every adversary, the observing of Thy commandments, and an acceptable defense at the dread judgment seat of Thy Christ.`,note:`Basil, Appendix IV p.131 (Litany of Thanksgiving prayer). Confirmed different from Chrysostom's lt-07.`},"pba-06":{status:`encoded`,basil_page:132,mode:`quiet`,cue:`(quietly)`,text:`The Mystery of Thy dispensation, O Christ our God, has been accomplished and perfected as far as it was in our power; for we have had the memorial of Thy death; we have seen the type of Thy Resurrection; we have been filled with Thine unending life; we have enjoyed Thine inexhaustible food; which in the world to come be well-pleased to vouchsafe us all, through the grace of Thine Eternal Father, and Thy Holy and Good and Life-creating Spirit, now and ever, and unto ages of ages. Amen.`,note:`Basil, Appendix IV p.132. Marked with '*' and '(132)' in Chrysostom. RESOLVES the v17 naming puzzle: the appendix heads this 'PRAYER WHILE CONSUMING THE HOLY GIFTS: (See page 82)', which is why a search for a 'Prayer Behind the Ambo' heading across pp.115-132 found nothing. pba-06 is not the Prayer Behind the Amvon itself (that is the separate heading unit at p.82) but the prayer said quietly over the deacon as he consumes the Gifts — so the appendix heading and the marker agree, and the v17 conclusion that no distinct Basil version exists was wrong. Confirmed different text, encoded rather than deleted.`},"atd-20":{status:`encoded`,basil_page:null,text:`Thus concludes the Divine Liturgy of St. Basil the Great.`,note:`EDITORIAL, not from the source: Appendix IV ends at p.132 with the closing hymns and prints no closing rubric of its own, but leaving Chrysostom's line in the Basil view would be plainly wrong. Wording follows the book's own name for the Liturgy ('St. Basil the Great', as in its headings). basil_page is null to keep this visibly distinct from transcribed overrides.`},"atd-heading4":{status:`encoded`,basil_page:132,text:`AT THE LITURGY OF SAINT BASIL THE GREAT`,note:`Basil, Appendix IV p.132, which prints 'AFTER THE DISMISSAL AT THE LITURGY OF ST. BASIL THE GREAT' as one heading; 'AFTER THE DISMISSAL' is already carried by this movement's own earlier heading, so only the saint clause is overridden here. Page also prints a rubric note — 'At the Dismissal, St. Basil The Great, Archbishop of Cæsarea in Cappadocia, is commemorated in place of St. John Chrysostom' — which the dismissal assembler already handles (dismissal_assembler_spec §8.1).`},"atd-10":{status:`encoded`,basil_page:132,text:`Your proclamation has gone out into all the earth, for it was divinely taught by hearing your voice. You expounded the nature of creatures and ennobled the manners of men. O holy father of royal priesthood, entreat Christ God that our souls may be saved.`,note:`Basil's Troparion, Appendix IV p.132. Marked with '*' and '(132)' in Chrysostom — the one unit of this cluster the book itself flags. Like Chrysostom's own atd-10 it is printed in the modern 'you/your' register rather than the 'Thee/Thy' of the Liturgy proper; transcribed as printed, not harmonized.`},"atd-12":{status:`encoded`,basil_page:132,text:`You were revealed as the sure foundation of the Church, granting all men a lordship which cannot be taken away, sealing it with your precepts, O venerable and heavenly father.`,note:`Basil's Kontakion, Appendix IV p.132. No printed marker in Chrysostom — found by reading the page, and confirmed saint-specific. Modern 'you/your' register, as atd-10.`}},n={"b-cm-11a":{insert_after:`cm-11`,movement:`commemorations`,speaker:`priest`,mode:`quiet`,basil_page:127,text:`Remember, O God, those who are in courts, in mines, in exile, in harsh labor, and those in any kind of affliction, necessity, or distress. Remember, O Lord our God, all those who entreat Thy great loving-kindness; those who love us and those who hate us; those who have asked us to pray for them, unworthy though we be; and remember all Thy people O Lord, our God. Pour out Thy rich mercy upon all of them, granting them all the petitions, which are for their salvation.`,note:`Basil, Appendix IV p.127. Third of four editorial units from the continuous pp.126-128 paragraph (spec v20); Chrysostom has no counterpart, so it is inserted after cm-11 rather than overriding. Quiet, continuing the same priest's prayer. Punctuation as printed, including 'all Thy people O Lord, our God' without a comma before 'O Lord'.`},"b-cm-11b":{insert_after:`b-cm-11a`,movement:`commemorations`,speaker:`priest`,mode:`quiet`,basil_page:127,text:`And remember, Thyself, O God, all those whom we have not remembered through ignorance, forgetfulness or the multitude of names; since Thou knowest the name and age of each, even from his mother's womb. For Thou, O Lord, art the Helper of the helpless, the Hope of the hopeless, the Savior of the bestormed, the Haven of the voyager, the Physician of the sick. Be all things to all men, O Thou Who knowest each man and his request, his home and his need. Deliver this city {{(or village, or holy habitation)}}, O Lord, and every city and country, from famine, plague, earthquake, flood, fire, sword, invasion by enemies, and civil war.`,note:`Basil, Appendix IV pp.127-128. Last of four editorial units from the continuous pp.126-128 paragraph (spec v20); chained after b-cm-11a. Closes with the 'Deliver this city' sentence that v16 had placed in cm-16's slot, after the Exclamation; the source says it here, before it. Two source typos corrected on Bill's approval: p.128 'Be all things to all me' encoded as 'men'; 'flood fire, sword' encoded as 'flood, fire, sword'. 'Bestormed' is the translation's own word, left as printed.`},"b-cm-16a":{insert_after:`cm-16`,movement:`commemorations`,speaker:`priest`,mode:`quiet`,basil_page:129,text:`Let none of us who stand about Thy holy altar be put to confusion. Visit us with Thy loving-kindness, O Lord; manifest Thyself to us through Thy rich compassions. Grant us seasonable and healthful weather; send gentle showers upon the earth so that it may bear fruit; bless the crown of the year with Thy goodness. Prevent schisms among the churches; pacify the ragings of the pagans; quickly destroy the uprisings of heresies by the Power of Thy Holy Spirit. Receive us all into Thy Kingdom, showing us to be sons of the light and sons of the day. Grant us Thy peace and Thy love, O Lord our God, for Thou hast given all things to us.`,note:`Basil, Appendix IV p.129. Continuation of the quiet prayer begun in cm-16 (p.128); the source prints it as one paragraph across the page break, split here editorially at the page turn (spec v20). Chrysostom has no counterpart between cm-16 and the 'And grant that with one mouth' Exclamation, so it is inserted rather than overriding. Capitalisation as printed ('Power', 'Kingdom').`},"b-ae-18a":{insert_after:`ae-18`,movement:`anaphora_epiclesis`,speaker:`priest`,mode:null,basil_page:124,text:`Shed for the life of the world.`,note:`Basil, Appendix IV p.124. Printed between the deacon's 'Amen.' (ae-18) and 'Amen. Bless both, Master.' (ae-20); Chrysostom has no such line, so it is inserted rather than overridden.`}},r=Object.entries(n);function i(n){if(n!==`basil`)return e;let i=[];for(let n of e){let e=t[n.id];e?e.status===`not_yet_encoded`?i.push({...n,basilPending:!0,basilPage:e.basil_page,basilInferred:!!e.inferred}):i.push({...n,text:e.text,mode:e.mode===void 0?n.mode:e.mode,cue:e.cue,pointing:e.pointing===void 0?n.pointing:e.pointing,note:e.note,basilOverride:!0,basilPage:e.basil_page}):i.push(n);let a=n.id,o=!0;for(;o;){o=!1;for(let[e,t]of r)if(t.insert_after===a){i.push({id:e,movement:t.movement===void 0?n.movement:t.movement,speaker:t.speaker,mode:t.mode===void 0?null:t.mode,cue:t.cue,text:t.text,pointing:t.pointing===void 0?null:t.pointing,note:t.note,basilInsert:!0,basilPage:t.basil_page,insertAfter:t.insert_after}),a=e,o=!0;break}}}return i}export{n as BASIL_INSERTS,t as BASIL_OVERRIDES,e as LITURGY_CHRYSOSTOM,i as getLiturgy};